/**
 * Real Cloudflare adapter for AppProviderApi — Story 2.17.
 *
 * Ports the HTTP scaffolding from the v1 cloudflare-client.ts reference:
 * request<T>, bearer auth, CfEnvelope, CloudflareApiError.
 *
 * apiBase and compatibilityDate are injected — no URL literal, no version
 * literal, no process.env read in this file (AD-12).
 */

import type {
  AppProviderApi,
  OpenUploadSessionParams,
  OpenUploadSessionResult,
  UploadAssetsParams,
  UploadScriptParams,
  ProvisionBucketParams,
  ProvisionDatabaseParams,
  ProvisionDatabaseResult,
  ApplyMigrationParams,
  ProbeHealthParams,
  ProbeHealthResult,
  DeleteAppParams,
  MigrationLedgerEntry,
  ReadMigrationLedgerParams,
} from './provider-api.port.js';
import {
  assertApplyMigrationContract,
  assertDeleteAppContract,
  assertOpenUploadSessionContract,
  assertProbeHealthContract,
  assertProvisionBucketContract,
  assertProvisionDatabaseContract,
  assertReadMigrationLedgerContract,
  assertUploadAssetsContract,
  assertUploadScriptContract,
} from './provider-contract.js';
import {
  MIGRATION_LEDGER_DDL,
  MIGRATION_LEDGER_TABLE,
  splitMigrationStatements,
} from './migration-statements.js';
import { assetContentType } from './asset-content-type.js';
import { PROBE_HEADER, PROBE_APP_HEADER } from './probe.js';
import { slotScriptName } from './slots.js';
import type { AppSlot } from './registry.js';

// ---------------------------------------------------------------------------
// Config
// ---------------------------------------------------------------------------

export interface CloudflareProviderConfig {
  accountId: string;
  apiToken: string;
  dispatchNamespace: string;
  /** Injected — e.g. 'https://api.cloudflare.com/client/v4'. No default here. */
  apiBase: string;
  /** Injected — e.g. '2026-07-01'. No default here. */
  compatibilityDate: string;
  /** Override for unit tests so no network is used. */
  fetchImpl?: typeof fetch;
}

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

/**
 * A delete call succeeded but the resource is still there.
 *
 * The provider answers 200 for a deleted script on every per-script endpoint —
 * `/scripts/{name}` returns a result body and `/scripts/{name}/bindings` returns an
 * empty array — so a 200 from DELETE is not evidence that anything was removed.
 * Destroy must fail loudly here: its caller keeps the tombstone and re-drives,
 * whereas reporting success would strand a live script with no record of it.
 */
export class ProviderDeleteIncompleteError extends Error {
  constructor(readonly remaining: string[]) {
    super(`delete reported success but these resources still exist: ${remaining.join(', ')}`);
    this.name = 'ProviderDeleteIncompleteError';
  }
}

export class CloudflareApiError extends Error {
  constructor(
    message: string,
    readonly status: number,
    readonly errors: unknown[],
  ) {
    super(message);
    this.name = 'CloudflareApiError';
  }
}

// ---------------------------------------------------------------------------
// Internal types
// ---------------------------------------------------------------------------

interface CfEnvelope<T> {
  success: boolean;
  errors: Array<{ code: number; message: string }>;
  result: T;
}

interface SessionState {
  slot: string;
  scriptName: string;
  completionToken?: string;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

// ponytail: module-level counter — sessions are per-process and short-lived
let _sessionCounter = 0;

function isNotFound(err: unknown): boolean {
  if (!(err instanceof CloudflareApiError)) return false;
  if (err.status === 404) return true;
  const msg = err.message.toLowerCase();
  if (msg.includes('not found')) return true;
  return (err.errors as Array<{ message?: string }>).some((e) =>
    e?.message?.toLowerCase().includes('not found'),
  );
}

/**
 * R2 error codes for "the bucket you tried to create already exists".
 * 10004 is what the live API answers for a bucket you own ("The bucket you tried
 * to create already exists, and you own it." — observed against the real account,
 * 2026-08-03); 10073 is the SDK-documented BucketConflict. Both are the idempotent
 * outcome and both are swallowed.
 */
const R2_BUCKET_ALREADY_EXISTS = new Set([10004, 10073]);

/**
 * R2 error code for "R2 is not enabled on the account" — observed live as
 * `403 {code:10042}` on the bucket-list GET; assumed symmetric for the lifecycle
 * PUT and bucket DELETE (if that assumption is wrong the teardown fails closed
 * and destroys keep blocking, i.e. today's behaviour — it cannot get worse).
 */
const R2_NOT_ENABLED = 10042;

/**
 * Matches by error code, never HTTP status — 10042 rides a 403, and swallowing
 * 403s generally would hide real token/scope failures. R2-off is deterministic
 * account state no tombstone re-drive ever heals, so the bucket teardown treats
 * it as "no bucket infrastructure exists" and skips, exactly like the
 * bucket-absent 404 (SPEC-destroy-tolerates-r2-disabled). Deploy-time
 * provisionBucket deliberately does NOT use this: a bucket-declaring App must
 * fail loudly on an account without R2.
 */
function isR2Disabled(err: unknown): boolean {
  if (!(err instanceof CloudflareApiError)) return false;
  return (err.errors as Array<{ code?: number }>).some((e) => e?.code === R2_NOT_ENABLED);
}

/**
 * Matches on the error code, never the HTTP status: `TooManyBuckets` (10009) and
 * `R2_NOT_ENABLED` are both 4xx and must propagate AT PROVISION TIME — a
 * bucket-declaring App cannot deploy onto an account without R2 (the destroy
 * path's isR2Disabled above deliberately makes the opposite call). Swallowing by
 * status is how "R2 is switched off" would be reported as "the bucket already
 * exists".
 */
function isAlreadyExists(err: unknown): boolean {
  if (!(err instanceof CloudflareApiError)) return false;
  return (err.errors as Array<{ code?: number }>).some(
    (e) => typeof e?.code === 'number' && R2_BUCKET_ALREADY_EXISTS.has(e.code),
  );
}

// ---------------------------------------------------------------------------
// Adapter
// ---------------------------------------------------------------------------

export class CloudflareProviderApi implements AppProviderApi {
  private readonly fetchImpl: typeof fetch;
  private readonly sessions = new Map<string, SessionState>();

  constructor(private readonly config: CloudflareProviderConfig) {
    this.fetchImpl = config.fetchImpl ?? globalThis.fetch.bind(globalThis);
  }

  // -------------------------------------------------------------------------
  // HTTP core (ported from cloudflare-client.ts reference)
  // -------------------------------------------------------------------------

  private async request<T>(
    path: string,
    init: RequestInit = {},
    /** Replaces apiToken when present (used for CF asset-upload bearer). */
    bearerOverride?: string,
  ): Promise<T> {
    const headers: Record<string, string> = {
      ...(init.headers as Record<string, string> | undefined),
      Authorization: `Bearer ${bearerOverride ?? this.config.apiToken}`,
    };
    if (typeof init.body === 'string') {
      headers['Content-Type'] = 'application/json';
    }
    const res = await this.fetchImpl(`${this.config.apiBase}${path}`, { ...init, headers });
    let body: CfEnvelope<T>;
    try {
      body = (await res.json()) as CfEnvelope<T>;
    } catch {
      // A gateway/proxy error (502 HTML, 204 No Content, rate-limit text) must
      // surface as a typed CloudflareApiError so callers' catch paths — including
      // isNotFound() during idempotent delete — classify it correctly.
      throw new CloudflareApiError(
        `Cloudflare API ${path} returned a non-JSON response`,
        res.status,
        [],
      );
    }
    if (!res.ok || !body.success) {
      const detail =
        body.errors?.map((e) => `${e.code}: ${e.message}`).join('; ') || res.statusText;
      throw new CloudflareApiError(
        `Cloudflare API ${path} failed: ${detail}`,
        res.status,
        body.errors ?? [],
      );
    }
    return body.result;
  }

  // -------------------------------------------------------------------------
  // Three-call asset flow (AD-9)
  // -------------------------------------------------------------------------

  openUploadSession(params: OpenUploadSessionParams): Promise<OpenUploadSessionResult> {
    assertOpenUploadSessionContract(params);
    const sessionId = `cf-${++_sessionCounter}-${Date.now()}`;
    this.sessions.set(sessionId, {
      slot: params.slot,
      scriptName: slotScriptName(params.appId, params.slot as AppSlot),
    });
    return Promise.resolve({ sessionId });
  }

  async uploadAssets(params: UploadAssetsParams): Promise<void> {
    const session = this.sessions.get(params.sessionId);
    if (!session) throw new Error(`Unknown sessionId: ${params.sessionId}`);

    // Build the provider manifest {publish path: {hash, size}} and a hash→bytes map
    // for the bucket upload phase. Both the path and the tenant-salted hash come from
    // buildAssetManifest: the provider addresses assets by path, and the salt must
    // reach the account or AD-9's per-App key space exists only in our own module.
    assertUploadAssetsContract(params);
    const byContentHash: Record<string, { bytes: Uint8Array; contentType: string }> = {};
    const manifest: Record<string, { hash: string; size: number }> = {};
    for (const [path, { hash, bytes }] of Object.entries(params.assets)) {
      manifest[path] = { hash, size: bytes.length };
      // The content type must be carried per file: the provider serves each asset
      // back with the type declared at upload, and an untyped part is served with
      // no content-type at all — which no browser will execute or style.
      byContentHash[hash] = { bytes, contentType: assetContentType(path) };
    }

    const scriptBase =
      `/accounts/${this.config.accountId}/workers/dispatch/namespaces/` +
      `${this.config.dispatchNamespace}/scripts/${session.scriptName}`;

    const sessionRes = await this.request<{ jwt: string; buckets: string[][] }>(
      `${scriptBase}/assets-upload-session`,
      { method: 'POST', body: JSON.stringify({ manifest }) },
    );

    // completionToken starts as session jwt; updated by each bucket upload
    // (buckets:[] → session jwt is already the completion token).
    let completionToken: string = sessionRes.jwt;
    for (const bucket of sessionRes.buckets) {
      const form = new FormData();
      for (const hash of bucket) {
        const asset = byContentHash[hash];
        if (!asset) throw new Error(`Bucket requested hash ${hash} not in uploaded assets`);
        // A File (not a bare string) so the part carries the asset's MIME type.
        // The body is base64 because the request is made with ?base64=true.
        form.set(
          hash,
          new File([Buffer.from(asset.bytes).toString('base64')], hash, {
            type: asset.contentType,
          }),
        );
      }
      // Bearer is the session jwt for all bucket uploads; response gives next token.
      // The result is an object carrying the token — `{ "jwt": "..." }` — not a bare
      // string. Assigning the object straight through made the final script upload
      // fail with "cannot unmarshal object into Go struct field Assets.jwt".
      const uploadResult = await this.request<{ jwt?: string } | null>(
        `/accounts/${this.config.accountId}/workers/assets/upload?base64=true`,
        { method: 'POST', body: form },
        sessionRes.jwt,
      );
      if (uploadResult?.jwt) completionToken = uploadResult.jwt;
    }

    session.completionToken = completionToken;
  }

  async uploadScript(params: UploadScriptParams): Promise<void> {
    assertUploadScriptContract(params);
    const session = this.sessions.get(params.sessionId);
    if (!session) throw new Error(`Unknown sessionId: ${params.sessionId}`);
    if (params.slot !== session.slot) {
      // Guard against a caller opening a session for one slot and committing to
      // another — that would silently deploy to the wrong slot (AD-11 fail-closed).
      throw new Error(
        `uploadScript slot '${params.slot}' does not match session slot '${session.slot}'`,
      );
    }
    if (!session.completionToken) {
      throw new Error('uploadScript called before uploadAssets completed (no completion token)');
    }

    // ASSETS binding is always present; declared bindings are added per type.
    // keep_bindings: [] means "keep nothing from the previous upload" — the full
    // binding set is governed by what we declare here, preventing cross-tenant bleed.
    // R2's metadata field is bucket_name, not an id — the bucket is its name
    // (verified against Cloudflare's multipart-upload-metadata reference).
    const cfDeclaredBindings = params.bindings.map((b) =>
      b.type === 'd1'
        ? { type: 'd1' as const, name: b.name, database_id: b.id }
        : { type: 'r2_bucket' as const, name: b.name, bucket_name: b.bucketName },
    );
    // The App's own build declared the runtime it needs; honour it. Uploading a
    // bundle under different compatibility settings than it was built with is how a
    // Worker importing node builtins reached the account without `nodejs_compat`.
    const metadata = {
      main_module: 'worker.mjs',
      compatibility_date: params.runtime?.compatibilityDate ?? this.config.compatibilityDate,
      ...(params.runtime?.compatibilityFlags?.length
        ? { compatibility_flags: params.runtime.compatibilityFlags }
        : {}),
      assets: {
        jwt: session.completionToken,
        config: { not_found_handling: 'single-page-application' },
      },
      bindings: [{ type: 'assets' as const, name: 'ASSETS' }, ...cfDeclaredBindings],
      keep_bindings: [] as string[],
    };
    const form = new FormData();
    form.set('metadata', JSON.stringify(metadata));
    // new Uint8Array(params.script) copies into a plain ArrayBuffer (BlobPart-compatible)
    form.set(
      'worker.mjs',
      new File([new Uint8Array(params.script)], 'worker.mjs', {
        type: 'application/javascript+module',
      }),
    );
    try {
      await this.request(
        `/accounts/${this.config.accountId}/workers/dispatch/namespaces/` +
          `${this.config.dispatchNamespace}/scripts/${session.scriptName}`,
        { method: 'PUT', body: form },
      );
    } finally {
      // uploadScript is the terminal call of the three-call flow — drop the
      // session either way so the map does not grow unbounded over the worker's
      // lifetime. A retry re-opens a fresh session.
      this.sessions.delete(params.sessionId);
    }
  }

  // -------------------------------------------------------------------------
  // D1 operations (AD-10, AD-15)
  // -------------------------------------------------------------------------

  async provisionDatabase(params: ProvisionDatabaseParams): Promise<ProvisionDatabaseResult> {
    assertProvisionDatabaseContract(params);
    const result = await this.request<{ uuid: string }>(
      `/accounts/${this.config.accountId}/d1/database`,
      { method: 'POST', body: JSON.stringify({ name: `app-${params.appId}` }) },
    );
    if (!result?.uuid) {
      // Fail fast rather than persist `undefined` as the databaseId and later
      // issue calls against `/d1/database/undefined/query`.
      throw new CloudflareApiError(
        'provisionDatabase: provider response missing database uuid',
        0,
        [],
      );
    }
    return { databaseId: result.uuid };
  }

  // -------------------------------------------------------------------------
  // R2 operations (AD-18, ADR-0027)
  // -------------------------------------------------------------------------

  /** Idempotently create the App's bucket. */
  async provisionBucket(params: ProvisionBucketParams): Promise<void> {
    assertProvisionBucketContract(params);
    try {
      await this.request(`/accounts/${this.config.accountId}/r2/buckets`, {
        method: 'POST',
        body: JSON.stringify({ name: `app-${params.appId}` }),
      });
    } catch (err) {
      if (!isAlreadyExists(err)) throw err;
    }
  }

  /**
   * One D1 REST query. Every ledger and migration statement goes through here.
   *
   * The return type drops the per-statement `success`/`meta`/`errors` deliberately; it is
   * not a check waiting to be restored. A `/query` failure is reported at the *envelope*,
   * with an empty `result` — observed against the real API, not inferred from docs:
   *
   *   SELECT * FROM a_table_that_does_not_exist;
   *   → {"result":[],"success":false,"errors":[{"code":7500,"message":"no such table: ..."}]}
   *
   *   SELECT 1 AS ok;
   *   → {"result":[{"results":[{"ok":1}],"success":true,"meta":{…}}],"success":true,"errors":[]}
   *
   * `request()` already throws on the first shape, so the nested `success` is reachable only
   * once the envelope succeeded — where it is always `true`. Callers send exactly one
   * statement per call (see splitMigrationStatements), so there is no multi-statement case
   * in which the envelope and a nested flag could disagree.
   */
  private async d1Query<T = unknown>(
    databaseId: string,
    sql: string,
    params: unknown[] = [],
  ): Promise<Array<{ results?: T[] }>> {
    return this.request<Array<{ results?: T[] }>>(
      `/accounts/${this.config.accountId}/d1/database/${databaseId}/query`,
      { method: 'POST', body: JSON.stringify({ sql, params }) },
    );
  }

  async readMigrationLedger(params: ReadMigrationLedgerParams): Promise<MigrationLedgerEntry[]> {
    assertReadMigrationLedgerContract(params);
    // Idempotent create on every read: the ledger then works on a database provisioned
    // before it existed, with no ordering dependency on provisioning.
    await this.d1Query(params.databaseId, MIGRATION_LEDGER_DDL);
    const result = await this.d1Query<{ ordinal: number; hash: string; status: string }>(
      params.databaseId,
      `SELECT ordinal, hash, status FROM ${MIGRATION_LEDGER_TABLE} ORDER BY ordinal`,
    );
    const rows = result[0]?.results ?? [];
    return rows.map((row) => ({
      ordinal: Number(row.ordinal),
      hash: String(row.hash),
      // Any status that is not exactly 'applied' is treated as unfinished. Defaulting the
      // other way would let a row we cannot interpret read as a completed migration.
      status: row.status === 'applied' ? 'applied' : 'applying',
    }));
  }

  async applyMigration(params: ApplyMigrationParams): Promise<void> {
    assertApplyMigrationContract(params);
    const { databaseId, ordinal, hash, sql } = params;
    const now = Math.floor(Date.now() / 1000);

    // Phase 1. A plain INSERT, not INSERT OR IGNORE: deploy has already filtered applied
    // ordinals, so a primary-key conflict here can only mean that filter is wrong. That
    // conflict is a wanted second line of defence against double-apply.
    await this.d1Query(
      databaseId,
      `INSERT INTO ${MIGRATION_LEDGER_TABLE} (ordinal, hash, status, started_at) VALUES (?, ?, ?, ?)`,
      [ordinal, hash, 'applying', now],
    );

    // Phase 2. One statement per call. D1's batch/transaction APIs are Worker-only and
    // explicit BEGIN/COMMIT is rejected, so multi-statement atomicity is not available at
    // all — issuing them individually at least makes the failure point deterministic.
    for (const statement of splitMigrationStatements(sql)) {
      await this.d1Query(databaseId, statement);
    }

    // Phase 3. Reached only if every statement succeeded. A throw above leaves the row
    // `applying`, and the next deploy refuses that ordinal by name rather than guessing.
    await this.d1Query(
      databaseId,
      `UPDATE ${MIGRATION_LEDGER_TABLE} SET status = ?, applied_at = ? WHERE ordinal = ?`,
      ['applied', Math.floor(Date.now() / 1000), ordinal],
    );
  }

  // -------------------------------------------------------------------------
  // Delete (AD-18) — idempotent: 404 / not-found swallowed
  // -------------------------------------------------------------------------

  async deleteApp(params: DeleteAppParams): Promise<void> {
    assertDeleteAppContract(params);
    for (const slot of params.slots) {
      const scriptName = slotScriptName(params.appId, slot as AppSlot);
      try {
        await this.request(
          `/accounts/${this.config.accountId}/workers/dispatch/namespaces/` +
            `${this.config.dispatchNamespace}/scripts/${scriptName}?force=true`,
          { method: 'DELETE' },
        );
      } catch (err) {
        if (!isNotFound(err)) throw err;
      }
    }

    if (params.databaseId) {
      try {
        await this.request(`/accounts/${this.config.accountId}/d1/database/${params.databaseId}`, {
          method: 'DELETE',
        });
      } catch (err) {
        if (!isNotFound(err)) throw err;
      }
    }

    // Bucket teardown — always attempted, never required (the name is derived, so
    // there is no record of whether this App ever declared one). A non-empty bucket
    // answers 409 BucketNotEmpty and must NOT fail the destroy: destroyAppWorkflow
    // has no retry loop that could outlast a 24-hour expiry, and throwing here would
    // abort cleanupAndFinalize before archives, version records, the registry row and
    // authz tuples are reclaimed. So: set an expire-after-1-day lifecycle rule, then
    // attempt the delete, and block only when the RULE could not be set on a bucket
    // that survives on a WORKING R2 account — the one case where nothing will ever
    // empty it. An R2-disabled answer (10042) on either call is treated as
    // bucket-absent instead: no infrastructure exists to tear down, and blocking
    // would be permanent (DW-70 records the emptied-but-never-deleted residue this
    // deliberately leaves; Linear DOC-855 records the R2-off skip's residue).
    const bucketName = `app-${params.appId}`;
    let bucketMissing = false;
    let lifecycleSet = false;
    try {
      await this.request(`/accounts/${this.config.accountId}/r2/buckets/${bucketName}/lifecycle`, {
        method: 'PUT',
        // maxAge is SECONDS (wrangler computes days * 86400 — a bare 1 would expire
        // objects after one second). conditions: {} is the all-objects form, and PUT
        // replaces the entire rules collection; these buckets are per-App and nothing
        // else manages their rules, so a single-element array is deliberate.
        body: JSON.stringify({
          rules: [
            {
              id: 'mfg-destroy-expire',
              enabled: true,
              conditions: {},
              deleteObjectsTransition: { condition: { type: 'Age', maxAge: 86_400 } },
            },
          ],
        }),
      });
      lifecycleSet = true;
    } catch (err) {
      // 404: the bucket does not exist (never declared, or already deleted) — done.
      // 10042: R2 is disabled on the account — no bucket infrastructure exists to
      // tear down, and blocking would strand every App's destroy permanently.
      // Anything else: leave lifecycleSet false; the delete below may still reclaim it.
      if (isNotFound(err) || isR2Disabled(err)) bucketMissing = true;
    }
    let bucketRemains = false;
    if (!bucketMissing) {
      try {
        await this.request(`/accounts/${this.config.accountId}/r2/buckets/${bucketName}`, {
          method: 'DELETE',
        });
      } catch (err) {
        // 404 = same terminal state as deleted; 10042 = R2 went disabled between the
        // two calls (mid-toggle) — no infrastructure remains to empty, same skip as
        // above. Anything else (409 BucketNotEmpty included) means the bucket
        // survives and the lifecycle rule decides whether that is acceptable.
        if (!isNotFound(err) && !isR2Disabled(err)) bucketRemains = true;
      }
    }

    // Confirm absence rather than trusting the delete responses. Both listings are
    // immediately consistent after a delete (verified against the account), so a
    // survivor here is a real one, not a read racing the write.
    const remaining: string[] = [];
    const scripts = await this.listNamespaceScripts();
    for (const slot of params.slots) {
      const scriptName = slotScriptName(params.appId, slot as AppSlot);
      if (scripts.includes(scriptName)) remaining.push(`script ${scriptName}`);
    }
    if (params.databaseId && (await this.databaseExists(params.databaseId))) {
      remaining.push(`database ${params.databaseId}`);
    }
    if (bucketRemains && !lifecycleSet) remaining.push(`bucket ${bucketName}`);
    if (remaining.length) throw new ProviderDeleteIncompleteError(remaining);
  }

  /** Whether a D1 database is still listed on the account. */
  private async databaseExists(databaseId: string): Promise<boolean> {
    const databases = await this.request<Array<{ uuid?: string }>>(
      `/accounts/${this.config.accountId}/d1/database`,
    );
    return (databases ?? []).some((d) => d.uuid === databaseId);
  }

  /**
   * Script names present in the dispatch namespace — the only absence proof the
   * provider offers. `/scripts/{name}` and `/scripts/{name}/bindings` both answer
   * 200 for a script that was successfully deleted, so a delete can only be
   * confirmed by the name dropping out of this listing.
   */
  async listNamespaceScripts(): Promise<string[]> {
    const result = await this.request<Array<{ id?: string; script_name?: string }>>(
      `/accounts/${this.config.accountId}/workers/dispatch/namespaces/` +
        `${this.config.dispatchNamespace}/scripts`,
    );
    return (result ?? []).flatMap((s) => {
      const name = s.id ?? s.script_name;
      return name ? [name] : [];
    });
  }

  // -------------------------------------------------------------------------
  // Health probe (AD-15) — GETs the deployed edge, not the CF API base
  // -------------------------------------------------------------------------

  /**
   * Health-check the staging slot by sending a GET to the deployed edge
   * (`https://{appHost}/`) with the signed probe + App headers.
   * This goes through the real Cloudflare edge (not `this.request`), so
   * `fetchImpl` must resolve the external hostname, which it does in prod
   * (global fetch) and in tests (injected mock).
   */
  async probeHealth(params: ProbeHealthParams): Promise<ProbeHealthResult> {
    assertProbeHealthContract(params);
    const res = await this.fetchImpl(`https://${params.appHost}/`, {
      headers: {
        [PROBE_HEADER]: params.probeSignature,
        [PROBE_APP_HEADER]: params.appId,
      },
      redirect: 'manual',
      signal: AbortSignal.timeout(10_000),
    });
    if (res.ok) return { ok: true };
    // Carry the reason. A bodyless 404 here is the edge refusing the probe (bad
    // signature or wrong secret); a 5xx with a body is the App Worker itself failing.
    let excerpt = '';
    try {
      excerpt = (await res.text()).slice(0, 300);
    } catch {
      // body already consumed or unreadable — the status alone is still worth reporting
    }
    return {
      ok: false,
      detail: `probe GET https://${params.appHost}/ → ${res.status}${excerpt ? `: ${excerpt}` : ' (no body)'}`,
    };
  }

  // -------------------------------------------------------------------------
  // Bindings read-back — confirms the upload set the expected bindings
  // -------------------------------------------------------------------------

  /**
   * Reads back the bindings currently attached to the given App slot.
   * Used by the smoke ladder to assert `ASSETS` (+ `DB`/`BUCKET` when declared) are
   * present. Reverse-maps every type uploadScript emits — a one-way mapping would
   * pass offline and fail live, because the ladder reads bindings back from here.
   */
  async getScriptBindings(params: {
    appId: string;
    slot: string;
  }): Promise<Array<{ type: string; name: string; id?: string; bucketName?: string }>> {
    const scriptName = slotScriptName(params.appId, params.slot as AppSlot);
    const result = await this.request<
      Array<{ type: string; name: string; database_id?: string; bucket_name?: string }>
    >(
      `/accounts/${this.config.accountId}/workers/dispatch/namespaces/` +
        `${this.config.dispatchNamespace}/scripts/${scriptName}/bindings`,
    );
    return (result ?? []).map((b) => ({
      type: b.type,
      name: b.name,
      ...(b.database_id !== undefined ? { id: b.database_id } : {}),
      ...(b.bucket_name !== undefined ? { bucketName: b.bucket_name } : {}),
    }));
  }
}
