import type { BundleEntry } from './validate.js';
import type { AppMigration } from './manifest.js';

/** Domain record for a saved, immutable App Version snapshot. */
export interface AppVersionRecord {
  versionId: string;
  appId: string;
  taskId: string;
  creatorMembershipId: string;
  archiveKey: string;
  archiveSha256: string;
  thumbnailKey?: string;
  schemaFingerprint: string;
  migrations: AppMigration[];
  createdAt: Date;
}

/** Input to saveAppVersion. versionId is minted by the caller so retries reuse the same id. */
export interface SaveAppVersionInput {
  versionId: string;
  appId: string;
  taskId: string;
  creatorMembershipId: string;
  entries: BundleEntry[];
  forbiddenLiterals: string[];
  thumbnailBytes?: Uint8Array;
}

export interface AppVersionStore {
  /**
   * Returns the most recently saved AppVersion for the app by createdAt, or null if none.
   * The latest version supplies the prior-schema context for validateBundle.
   */
  getLatestAppVersion(appId: string): Promise<AppVersionRecord | null>;
  /**
   * Returns a specific AppVersion by versionId, or null if not found.
   * Used by deploy (2.8) and rollback (2.14) to load a version by id.
   */
  getAppVersion(versionId: string): Promise<AppVersionRecord | null>;
  /**
   * Insert a AppVersion record. Idempotent on versionId: a retry with the same
   * versionId returns the ALREADY-STORED record unchanged (first write wins).
   * Returns the effective stored record so callers always reflect persisted state.
   */
  insertAppVersion(record: AppVersionRecord): Promise<AppVersionRecord>;

  /** Return all AppVersion records for an app. Empty if none. */
  listAppVersions(appId: string): Promise<AppVersionRecord[]>;

  /** Remove all AppVersion records for an app. No-op if none. */
  deleteAppVersions(appId: string): Promise<void>;
}

export class InMemoryAppVersionStore implements AppVersionStore {
  // ponytail: Map keyed by versionId; latest scan is O(n) — acceptable for tests only
  private records = new Map<string, AppVersionRecord>();

  async getLatestAppVersion(appId: string): Promise<AppVersionRecord | null> {
    let latest: AppVersionRecord | null = null;
    for (const r of this.records.values()) {
      if (r.appId !== appId) continue;
      if (!latest || r.createdAt > latest.createdAt) latest = r;
    }
    return latest;
  }

  async getAppVersion(versionId: string): Promise<AppVersionRecord | null> {
    return this.records.get(versionId) ?? null;
  }

  async insertAppVersion(record: AppVersionRecord): Promise<AppVersionRecord> {
    // ponytail: idempotent — same versionId is a Temporal retry; first write wins
    const existing = this.records.get(record.versionId);
    if (existing) return existing;
    const stored = { ...record, migrations: [...record.migrations] };
    this.records.set(record.versionId, stored);
    return stored;
  }

  async listAppVersions(appId: string): Promise<AppVersionRecord[]> {
    const result: AppVersionRecord[] = [];
    for (const r of this.records.values()) {
      if (r.appId === appId) result.push(r);
    }
    return result;
  }

  async deleteAppVersions(appId: string): Promise<void> {
    for (const [id, r] of this.records) {
      if (r.appId === appId) this.records.delete(id);
    }
  }
}
