/**
 * Object-store port — the seam for immutable App Bundle archive storage (AD-9).
 *
 * The real adapter a later story builds can wrap IStorageClient from
 * @mfg-agent/storage; this module imports nothing from it.
 */

import { FakeCallController } from './fake-call-controller.js';

/** Physical object-store namespace retained for backward compatibility. */
export const APP_OBJECT_STORAGE_PREFIX = 'app-archives/';

/** Map an App's logical object key to its deployed physical storage key. */
export const appStorageObjectKey = (logicalKey: string): string =>
  `${APP_OBJECT_STORAGE_PREFIX}${logicalKey}`;

/** Logical object-store key for an immutable App Version thumbnail. */
export const appThumbnailKey = (appId: string, versionId: string): string =>
  `apps/${appId}/thumbnails/${versionId}.png`;

// ---------------------------------------------------------------------------
// Domain errors
// ---------------------------------------------------------------------------

/** Thrown when putImmutable is called on a key that already exists (AD-9). */
export class ArchiveImmutabilityError extends Error {
  constructor(key: string) {
    super(`Archive key already exists and cannot be overwritten: ${key}`);
    this.name = 'ArchiveImmutabilityError';
  }
}

/** Thrown when get is called for a key that has not been stored. */
export class ArchiveNotFoundError extends Error {
  constructor(key: string) {
    super(`Archive key not found: ${key}`);
    this.name = 'ArchiveNotFoundError';
  }
}

// ---------------------------------------------------------------------------
// Port interface
// ---------------------------------------------------------------------------

export interface AppObjectStore {
  /**
   * Write `data` at `key`. Rejects with ArchiveImmutabilityError if `key`
   * already exists — archives are immutable (AD-9).
   */
  putImmutable(key: string, data: Uint8Array): Promise<void>;

  /**
   * Read the bytes stored at `key`. Rejects with ArchiveNotFoundError if
   * `key` has never been written.
   */
  get(key: string): Promise<Uint8Array>;

  /** Returns true if `key` has been written, false otherwise. */
  exists(key: string): Promise<boolean>;

  /** Remove the object at `key`. No-op if absent. */
  delete(key: string): Promise<void>;
}

// ---------------------------------------------------------------------------
// In-memory fake
// ---------------------------------------------------------------------------

class InMemoryObjectStore implements AppObjectStore {
  private store = new Map<string, Uint8Array>();

  constructor(readonly controller: FakeCallController) {}

  putImmutable(key: string, data: Uint8Array): Promise<void> {
    return this.controller.gate('putImmutable', [key, data], () => {
      if (this.store.has(key)) throw new ArchiveImmutabilityError(key);
      this.store.set(key, data.slice());
    });
  }

  get(key: string): Promise<Uint8Array> {
    return this.controller.gate('get', [key], () => {
      const bytes = this.store.get(key);
      if (bytes === undefined) throw new ArchiveNotFoundError(key);
      return bytes.slice();
    });
  }

  exists(key: string): Promise<boolean> {
    return this.controller.gate('exists', [key], () => this.store.has(key));
  }

  delete(key: string): Promise<void> {
    return this.controller.gate('delete', [key], () => {
      this.store.delete(key); // no-op if absent
    });
  }
}

// ---------------------------------------------------------------------------
// Factory
// ---------------------------------------------------------------------------

export function createInMemoryObjectStore(): {
  store: AppObjectStore;
  controller: FakeCallController;
} {
  const controller = new FakeCallController();
  return { store: new InMemoryObjectStore(controller), controller };
}
