/// <reference lib="webworker" />
import { base64urlEncode, base64urlDecode } from './base64url.js';

export const HANDOFF_LABEL = 'mfg-agent:apps-edge:handoff:v1';
/** Maximum token lifetime in seconds. Tokens must be redeemed quickly. */
export const HANDOFF_TTL_SECONDS = 300;
/** Shared query-param name carrying the handoff token. Used by control-plane (Story 3.2) and dispatch Worker (Story 3.3). */
export const HANDOFF_QUERY_PARAM = '__mfg_handoff';
/** Symmetric clock-skew tolerance in seconds applied to iat and exp. */
export const HANDOFF_SKEW_SECONDS = 10;

const enc = new TextEncoder();
const dec = new TextDecoder();

// ---------------------------------------------------------------------------
// Burn-store port + in-memory fake
// ---------------------------------------------------------------------------

/** Atomic put-if-absent for single-use JTIs. */
export interface BurnStore {
  /** Returns true on first call for this jti, false if already burned. */
  tryBurn(jti: string): Promise<boolean>;
}

/**
 * @internal — for tests/dev only; a `Set` is per-isolate and provides NO
 * cross-isolate replay protection. Production must inject a durable, atomic
 * (compare-and-swap / conditional-write) BurnStore.
 */
export class InMemoryBurnStore implements BurnStore {
  private readonly burned = new Set<string>();

  async tryBurn(jti: string): Promise<boolean> {
    if (this.burned.has(jti)) return false;
    this.burned.add(jti);
    return true;
  }
}

// ---------------------------------------------------------------------------
// Internal types
// ---------------------------------------------------------------------------

/**
 * The anti-replay binding fields that verifyHandoffToken checks against the
 * caller-supplied `expected` object. The edge has a prior expectation for
 * these (app and generation from the registry row, user from peekHandoffUser,
 * host from the request hostname); Organization and Workspace have no prior
 * expectation and are carried as signed identity claims instead.
 */
export interface HandoffBinding {
  app: string;
  user: string;
  host: string;
  generation: number;
}

/** Full set of claims minted by the control plane and carried in the token. */
export interface HandoffClaims {
  app: string;
  user: string;
  host: string;
  org: string;
  workspace: string;
  generation: number;
}

interface HandoffPayload {
  app: string;
  user: string;
  host: string;
  org: string;
  workspace: string;
  generation: number;
  iat: number;
  exp: number;
  jti: string;
}

// ---------------------------------------------------------------------------
// Crypto helpers
// ---------------------------------------------------------------------------

async function deriveHandoffSubkey(secret: Uint8Array): Promise<CryptoKey> {
  const keyData = new Uint8Array(secret) as Uint8Array<ArrayBuffer>;
  const hkdfKey = await crypto.subtle.importKey('raw', keyData, 'HKDF', false, ['deriveKey']);
  return crypto.subtle.deriveKey(
    {
      name: 'HKDF',
      hash: 'SHA-256',
      salt: new Uint8Array(32) as Uint8Array<ArrayBuffer>,
      info: enc.encode(HANDOFF_LABEL) as Uint8Array<ArrayBuffer>,
    },
    hkdfKey,
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign', 'verify'],
  );
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Mint a short-lived single-use handoff token bound to
 * {app, user, host, generation}.
 * Wire format: base64url(JSON payload) + '.' + base64url(HMAC-SHA256 sig).
 */
export async function mintHandoffToken(
  secret: Uint8Array,
  claims: HandoffClaims,
  now = Date.now() / 1000,
): Promise<string> {
  const iat = Math.floor(now);
  const jtiBytes = crypto.getRandomValues(new Uint8Array(16) as Uint8Array<ArrayBuffer>);
  const payload: HandoffPayload = {
    app: claims.app,
    user: claims.user,
    host: claims.host,
    org: claims.org,
    workspace: claims.workspace,
    generation: claims.generation,
    iat,
    exp: iat + HANDOFF_TTL_SECONDS,
    jti: base64urlEncode(jtiBytes),
  };
  const key = await deriveHandoffSubkey(secret);
  const payloadB64 = base64urlEncode(
    enc.encode(JSON.stringify(payload)) as Uint8Array<ArrayBuffer>,
  );
  const sig = await crypto.subtle.sign(
    'HMAC',
    key,
    enc.encode(payloadB64) as Uint8Array<ArrayBuffer>,
  );
  return `${payloadB64}.${base64urlEncode(new Uint8Array(sig))}`;
}

/**
 * Read-only accessor: returns the `user` field from a token's payload segment
 * without verifying the signature. Used by the edge to supply `expected.user`
 * to `verifyHandoffToken` when the edge has no prior notion of the Viewer.
 * The HMAC signature (checked inside `verifyHandoffToken`) protects the claim.
 * Returns null on any malformed or missing input; never throws.
 */
export function peekHandoffUser(token: string): string | null {
  try {
    const dot = token.indexOf('.');
    if (dot === -1) return null;
    const payloadB64 = token.slice(0, dot);
    if (!payloadB64) return null;
    const payload = JSON.parse(dec.decode(base64urlDecode(payloadB64))) as Record<string, unknown>;
    return typeof payload['user'] === 'string' ? payload['user'] : null;
  } catch {
    return null;
  }
}

/**
 * Reason a verification failed. `store-unavailable` is deliberately distinct from
 * every token-defect reason: a burn store that cannot answer is an outage, not a
 * malformed or replayed token, and reporting it as one sends every diagnosis after
 * the Viewer instead of the store (DW-37).
 */
export const HANDOFF_STORE_UNAVAILABLE = 'store-unavailable';

export type HandoffVerifyResult =
  | { ok: true; claims: HandoffClaims }
  | { ok: false; reason: string };

/**
 * Verify a handoff token. On success, burns the jti atomically (single-use).
 * Returns failure without throwing on any invalid condition.
 * @param expected - the {app, user, host, generation} bindings to enforce
 *   (anti-replay and stale-generation rejection).
 *   Organization and Workspace are carried as signed identity claims, not bindings.
 * @param burnStore - atomic put-if-absent for jti replay prevention.
 */
export async function verifyHandoffToken(
  secret: Uint8Array,
  token: string,
  expected: HandoffBinding,
  burnStore: BurnStore,
  now = Date.now() / 1000,
): Promise<HandoffVerifyResult> {
  try {
    const dot = token.indexOf('.');
    if (dot === -1) return { ok: false, reason: 'malformed' };
    const payloadB64 = token.slice(0, dot);
    const sigB64 = token.slice(dot + 1);
    if (!payloadB64 || !sigB64) return { ok: false, reason: 'malformed' };

    const key = await deriveHandoffSubkey(secret);
    const valid = await crypto.subtle.verify(
      'HMAC',
      key,
      base64urlDecode(sigB64),
      enc.encode(payloadB64) as Uint8Array<ArrayBuffer>,
    );
    if (!valid) return { ok: false, reason: 'signature' };

    const payload = JSON.parse(dec.decode(base64urlDecode(payloadB64))) as HandoffPayload;

    // Runtime shape guard — defense-in-depth against mint-side bug or schema drift
    if (
      typeof payload.exp !== 'number' ||
      typeof payload.iat !== 'number' ||
      typeof payload.jti !== 'string' ||
      !payload.jti ||
      typeof payload.org !== 'string' ||
      !payload.org ||
      typeof payload.workspace !== 'string' ||
      !payload.workspace ||
      !Number.isInteger(payload.generation) ||
      payload.generation < 0
    )
      return { ok: false, reason: 'malformed' };

    // Expiry with symmetric clock-skew tolerance
    if (now > payload.exp + HANDOFF_SKEW_SECONDS) return { ok: false, reason: 'expired' };
    if (now < payload.iat - HANDOFF_SKEW_SECONDS) return { ok: false, reason: 'future' };

    // Binding checks (app/user/host/generation; org/workspace are carried identity claims)
    if (payload.app !== expected.app) return { ok: false, reason: 'app-mismatch' };
    if (payload.user !== expected.user) return { ok: false, reason: 'user-mismatch' };
    if (payload.host !== expected.host) return { ok: false, reason: 'host-mismatch' };
    if (payload.generation !== expected.generation) {
      return { ok: false, reason: 'generation-mismatch' };
    }

    // Atomic single-use burn — must succeed before reporting ok.
    // Scoped catch: the outer one below turns anything it sees into 'parse-error',
    // which would report a store outage as a malformed token and leave a possibly
    // half-committed burn indistinguishable from a garbled string (DW-37).
    let burned: boolean;
    try {
      burned = await burnStore.tryBurn(payload.jti);
    } catch {
      return { ok: false, reason: HANDOFF_STORE_UNAVAILABLE };
    }
    if (!burned) return { ok: false, reason: 'replayed' };

    return {
      ok: true,
      claims: {
        app: payload.app,
        user: payload.user,
        host: payload.host,
        org: payload.org,
        workspace: payload.workspace,
        generation: payload.generation,
      },
    };
  } catch {
    return { ok: false, reason: 'parse-error' };
  }
}
