export const SharingLevel = {
  Private: 'Private',
  Workspace: 'Workspace',
  Organization: 'Organization',
  Public: 'Public',
} as const;
export type SharingLevel = (typeof SharingLevel)[keyof typeof SharingLevel];

export const APP_RELATIONS = {
  PUBLIC: 'public',
  ORG: 'org',
  WORKSPACE_EDITOR: 'workspace_editor',
  WORKSPACE_VIEWER: 'workspace_viewer',
  REVOKING: 'revoking',
} as const;

export function deriveSharingLevel(relations: Iterable<string>): SharingLevel {
  const set = new Set(relations);
  if (set.has(APP_RELATIONS.PUBLIC)) return SharingLevel.Public;
  if (set.has(APP_RELATIONS.ORG)) return SharingLevel.Organization;
  if (set.has(APP_RELATIONS.WORKSPACE_EDITOR) || set.has(APP_RELATIONS.WORKSPACE_VIEWER))
    return SharingLevel.Workspace;
  return SharingLevel.Private;
}

// Precedence: Public(3) > Organization(2) > Workspace(1) > Private(0)
const SHARING_RANK: Record<SharingLevel, number> = {
  [SharingLevel.Private]: 0,
  [SharingLevel.Workspace]: 1,
  [SharingLevel.Organization]: 2,
  [SharingLevel.Public]: 3,
};

/** Returns true iff changing from → to narrows the permitted set. */
export function isNarrowing(from: SharingLevel, to: SharingLevel): boolean {
  return SHARING_RANK[to] < SHARING_RANK[from];
}

/** Maps a target sharing level to its complete set of SpiceDB grants. */
export function sharingLevelTuples(
  level: SharingLevel,
  orgId: string,
  workspaceIds: string[],
): { relation: string; subject: { objectType: string; objectId: string } }[] {
  switch (level) {
    case SharingLevel.Public:
      return [
        {
          relation: APP_RELATIONS.PUBLIC,
          subject: { objectType: 'public_user', objectId: '*' },
        },
        {
          relation: APP_RELATIONS.PUBLIC,
          subject: { objectType: 'membership', objectId: '*' },
        },
      ];
    case SharingLevel.Organization:
      return [{ relation: APP_RELATIONS.ORG, subject: { objectType: 'org', objectId: orgId } }];
    case SharingLevel.Workspace:
      return workspaceIds.map((workspaceId) => ({
        relation: APP_RELATIONS.WORKSPACE_VIEWER,
        subject: { objectType: 'workspace', objectId: workspaceId },
      }));
    case SharingLevel.Private:
      return [];
  }
}

/** True for relations owned by the replacement-style sharing transition. */
export function isAppSharingRelation(relation: string): boolean {
  return (
    relation === APP_RELATIONS.PUBLIC ||
    relation === APP_RELATIONS.ORG ||
    relation === APP_RELATIONS.WORKSPACE_VIEWER ||
    relation === APP_RELATIONS.WORKSPACE_EDITOR
  );
}
