export const APP_VERSION_SAVE_REJECTED = 'APP_VERSION_SAVE_REJECTED' as const;
export const APP_DEPLOY_HEALTH_CHECK_FAILED = 'APP_DEPLOY_HEALTH_CHECK_FAILED' as const;
export const APP_DEPLOYED = 'APP_DEPLOYED' as const;
export const APP_DESTROYED = 'APP_DESTROYED' as const;
export const APP_ACCESS_REFUSED = 'APP_ACCESS_REFUSED' as const;

export interface AppEvent {
  type: string;
  appId: string;
  /** Optional: absent on serving-plane events where no Task exists (NFR-7, e.g. APP_ACCESS_REFUSED). */
  taskId?: string;
  data: Record<string, unknown>;
}

export interface AppEventSink {
  emitAppEvent(evt: AppEvent): Promise<void>;
}

/** In-memory fake — records emitted events for test assertions. */
export class InMemoryAppEventSink implements AppEventSink {
  readonly emitted: AppEvent[] = [];

  async emitAppEvent(evt: AppEvent): Promise<void> {
    this.emitted.push({ ...evt, data: { ...evt.data } });
  }
}
