/**
 * Deploy domain orchestrator — Stories 2.8 / 2.9 / 2.10 / 2.11.
 *
 * Pure function over injected ports; no credentials, no HTTP, no Mongo.
 * Upload target is stagingSlot(live) (or INITIAL_SLOT on first deploy).
 *
 * Pipeline (ordering is a contract — AD-15):
 *   Step 1: openUploadSession  — open staging slot
 *   Step 2: uploadAssets       — stage assets by publish path, tenant-salted hashes
 *   Step 3: uploadScript       — commit point (worker-entry bytes only)
 *   Step 4: applyMigration × N — apply declared migrations in ordinal order
 *   Step 5: probeHealth        — health-check the staging slot with a signed probe
 *
 * The sole traffic-moving commit is the writeAppRegistryRow CAS flip at
 * the end — any earlier failure leaves the live slot untouched.
 */

import type {
  AppProviderApi,
  MigrationLedgerEntry,
  AppScriptBinding,
} from './provider-api.port.js';
import type { AppObjectStore } from './object-store.port.js';
import type { AppRegistryStore, AppSlot } from './registry.js';
import { writeAppRegistryRow } from './registry.js';
import { INITIAL_SLOT, stagingSlot } from './slots.js';
import type { AppVersionStore } from './app-version.js';
import { DeployFailedError } from './errors.js';
import { readBundleArchive } from './archive.js';
import { WORKER_ENTRY, ASSET_ROOT, isManifestPath, MIGRATIONS_DIR } from './layout.js';
import { buildAssetManifest } from './asset-manifest.js';
import { parseManifest } from './manifest.js';
import { hashMigration } from './fingerprint.js';
import type { AppRegistrationStore, AppRecord } from './registration.js';
import type { AppEventSink } from './app-events.js';
import { APP_DEPLOY_HEALTH_CHECK_FAILED, APP_DEPLOYED } from './app-events.js';
import { signProbe } from './probe.js';

const enc = new TextEncoder();
const dec = new TextDecoder();

export interface DeployAppVersionDeps {
  provider: AppProviderApi;
  registry: AppRegistryStore;
  objectStore: AppObjectStore;
  versionStore: AppVersionStore;
  appStore: AppRegistrationStore;
  events: AppEventSink;
  probeSecret: Uint8Array;
}

export interface DeployAppVersionInput {
  appId: string;
  appHost: string;
  versionId: string;
}

export type DeployAppVersionResult =
  | { status: 'deployed'; liveSlot: AppSlot }
  | { status: 'noop'; liveSlot: AppSlot };

export async function deployAppVersion(
  deps: DeployAppVersionDeps,
  input: DeployAppVersionInput,
): Promise<DeployAppVersionResult> {
  const version = await deps.versionStore.getAppVersion(input.versionId);
  if (!version || version.appId !== input.appId) throw new DeployFailedError('load-version');

  const current = await deps.registry.read(input.appHost);
  if (current?.deployed_version_id === input.versionId) {
    return { status: 'noop', liveSlot: current.live_slot };
  }

  const slot: AppSlot = current ? stagingSlot(current.live_slot) : INITIAL_SLOT;

  // Decode archive, split worker script from asset entries, build the
  // tenant-salted asset hashes by publish path, and resolve declared migrations by content
  // hash (AD-14) — all before any session is opened, so a failure here throws
  // a typed DeployFailedError and leaks no upload session.
  let script: Uint8Array;
  let assetUploads: Record<string, { hash: string; bytes: Uint8Array }>;
  let declaresDb = false;
  let declaresBucket = false;
  let runtime: { compatibilityDate: string; compatibilityFlags: string[] } | undefined;
  let migrations: { ordinal: number; sql: string; hash: string }[] = [];
  try {
    const archiveBytes = await deps.objectStore.get(version.archiveKey);
    const entries = readBundleArchive(archiveBytes);
    const worker = entries.find((e) => e.path === WORKER_ENTRY);
    if (!worker) throw new Error(`archive missing ${WORKER_ENTRY}`);
    script = typeof worker.content === 'string' ? enc.encode(worker.content) : worker.content;
    const assets = entries.filter((e) => e.path.startsWith(ASSET_ROOT));
    assetUploads = buildAssetManifest(input.appId, assets).assets;
    const manifestEntry = entries.find((e) => isManifestPath(e.path));
    if (manifestEntry) {
      const raw =
        typeof manifestEntry.content === 'string'
          ? manifestEntry.content
          : dec.decode(manifestEntry.content);
      const manifest = parseManifest(JSON.parse(raw));
      declaresDb = Boolean(manifest.database?.schema);
      declaresBucket = manifest.bucket === true;
      // The App's build declared the runtime it needs; carry it to the upload.
      runtime = manifest.runtime;

      // Index MIGRATIONS_DIR entries by content hash (AD-14: identity = ordinal + hash).
      // Fatal decoder: reject invalid UTF-8 rather than silently yielding U+FFFD
      // replacement characters (same boundary principle as archive.ts).
      const migDec = new TextDecoder('utf-8', { fatal: true });
      const sqlByHash = new Map<string, string>();
      for (const e of entries.filter((e) => e.path.startsWith(MIGRATIONS_DIR))) {
        const content = typeof e.content === 'string' ? e.content : migDec.decode(e.content);
        sqlByHash.set(hashMigration(content), content);
      }

      if (manifest.migrations.length && !manifest.database?.schema)
        throw new Error('migrations declared without a database');
      migrations = [...manifest.migrations]
        .sort((a, b) => a.ordinal - b.ordinal)
        .map((m) => {
          const sql = sqlByHash.get(m.hash);
          if (sql === undefined)
            throw new Error(`migration ${m.ordinal} has no file matching its hash`);
          return { ordinal: m.ordinal, sql, hash: m.hash };
        });
    }
  } catch (err) {
    throw new DeployFailedError('load-archive', { cause: err });
  }

  // DB provisioning (pipeline step 2): runs before any upload session is opened,
  // so a provision failure leaves the live slot and both script slots untouched.
  // Capture databaseId for migration step 4 below.
  let databaseId: string | undefined;
  if (declaresDb) {
    let app: AppRecord | null;
    try {
      app = await deps.appStore.findApp(input.appId);
    } catch (err) {
      throw new DeployFailedError('load-app', { cause: err });
    }
    if (!app) throw new DeployFailedError('load-app');
    if (app.databaseId) {
      databaseId = app.databaseId;
    } else {
      let provisionedId: string;
      try {
        ({ databaseId: provisionedId } = await deps.provider.provisionDatabase({
          appId: input.appId,
          organizationId: app.orgId,
        }));
      } catch (err) {
        throw new DeployFailedError('provision-database', { cause: err });
      }
      // Persist before any upload so a retry reads the id and never reprovisions.
      // (A crash in the window before this write can still orphan the provider DB;
      // the real adapter closes it with an idempotent create-if-exists — deferred.)
      try {
        await deps.appStore.setAppDatabaseId(input.appId, provisionedId);
      } catch (err) {
        throw new DeployFailedError('persist-database-id', { cause: err });
      }
      databaseId = provisionedId;
    }
  }

  // Bucket provisioning: same placement rule as the DB block above — before any
  // upload session, so a failure leaves the live slot and both script slots
  // untouched. Unlike D1 there is no id to capture and no store write: the name is
  // `app-{appId}`, derived, and the create swallows already-exists — naturally
  // idempotent, with no crash window between "provisioned" and "recorded" (DW-24
  // cannot arise because there is nothing to record).
  if (declaresBucket) {
    try {
      await deps.provider.provisionBucket({ appId: input.appId });
    } catch (err) {
      throw new DeployFailedError('provision-bucket', { cause: err });
    }
  }

  // Ledger reconciliation (AD-14). Runs before the upload session so a rewritten or
  // interrupted migration fails without provisioning an upload or touching a slot —
  // the refusal costs one read, and no SQL is issued.
  let outstanding = migrations;
  if (declaresDb && migrations.length > 0) {
    let ledger: MigrationLedgerEntry[];
    try {
      ledger = await deps.provider.readMigrationLedger({ databaseId: databaseId! });
    } catch (err) {
      throw new DeployFailedError('read-migration-ledger', { cause: err });
    }
    const byOrdinal = new Map(ledger.map((e) => [e.ordinal, e]));
    outstanding = [];
    for (const m of migrations) {
      const recorded = byOrdinal.get(m.ordinal);
      if (!recorded) {
        outstanding.push(m);
        continue;
      }
      if (recorded.status === 'applying') {
        // A previous deploy wrote the row and never returned. Whether the SQL landed is
        // unknowable from here, and both guesses corrupt the App: re-running may fail or
        // duplicate, skipping may leave the schema behind the code.
        throw new DeployFailedError('migration-interrupted', {
          cause: new Error(
            `migration ${m.ordinal} was interrupted while being applied; its outcome is ` +
              'unknown. Inspect the App Database, then either complete it and set the ' +
              `ledger row to 'applied', or delete the row if nothing landed.`,
          ),
        });
      }
      if (recorded.hash !== m.hash) {
        throw new DeployFailedError('migration-hash-mismatch', {
          cause: new Error(
            `migration ${m.ordinal} was applied with hash ${recorded.hash} but this bundle ` +
              `declares ${m.hash}; a migration is immutable once applied — add a new one`,
          ),
        });
      }
      // Recorded, applied, same hash: already done. Not re-applied — this is apply-once.
    }
    // Ledger ordinals absent from the manifest are ignored: restoring an earlier App
    // Version legitimately carries fewer migrations than the database has applied.
  }

  // Step 1: open upload session.
  let sessionId: string;
  try {
    const result = await deps.provider.openUploadSession({ appId: input.appId, slot });
    sessionId = result.sessionId;
  } catch (err) {
    throw new DeployFailedError('open-session', { cause: err });
  }

  // Step 2: stage assets by publish path (tenant-salted hashes; failure leaves slot untouched).
  try {
    await deps.provider.uploadAssets({ sessionId, assets: assetUploads });
  } catch (err) {
    throw new DeployFailedError('upload-assets', { cause: err });
  }

  // Step 3: upload worker-entry bytes — commit point.
  // Bindings: ASSETS always present (added by adapter); DB / BUCKET bindings added
  // per declaration, independently. keep_bindings handled by the adapter (never
  // implicit).
  const bindings: AppScriptBinding[] = [
    ...(declaresDb ? [{ type: 'd1' as const, name: 'DB', id: databaseId! }] : []),
    ...(declaresBucket
      ? [{ type: 'r2_bucket' as const, name: 'BUCKET', bucketName: `app-${input.appId}` }]
      : []),
  ];
  try {
    await deps.provider.uploadScript({
      sessionId,
      slot,
      script,
      disableDirectSubdomain: true, // AD-11: asserted by ports.source.test.ts and deploy.test.ts
      bindings,
      ...(runtime !== undefined ? { runtime } : {}),
    });
  } catch (err) {
    throw new DeployFailedError('upload-script', { cause: err });
  }

  // Step 4: apply outstanding migrations in ascending ordinal order (AD-14/AD-15).
  // Runs after the script commit and before the CAS registry flip so a migration
  // failure leaves the live slot untouched. Ordinals already recorded `applied` in the
  // ledger were filtered out above and are never offered to the provider again.
  for (const m of outstanding) {
    try {
      // ponytail: databaseId! safe — migrations require declaresDb, which always sets databaseId above
      await deps.provider.applyMigration({ databaseId: databaseId!, ...m });
    } catch (err) {
      throw new DeployFailedError('apply-migrations', { cause: err });
    }
  }

  // Step 5: health-check the staging slot with a signed probe (AD-15 / AC3).
  // Must run after every applyMigration and before the CAS flip (ordering contract).
  // Any failure in this phase — signing, transport, or an unhealthy result — is a
  // health-check failure: the typed DeployFailedError('health-check') must surface
  // (AC3's retrievable reason) and the CAS flip below must not run.
  let healthy = false;
  let cause: unknown;
  try {
    const probeSignature = await signProbe(deps.probeSecret, input.appHost, slot, input.appId);
    const probe = await deps.provider.probeHealth({
      slot,
      probeSignature,
      appHost: input.appHost,
      appId: input.appId,
    });
    healthy = probe.ok;
    // An unhealthy probe is not an exception, so without this the thrown
    // DeployFailedError('health-check') would carry no reason at all.
    if (!probe.ok && probe.detail) cause = new Error(probe.detail);
  } catch (err) {
    cause = err;
  }
  if (!healthy) {
    // Best-effort event: an event-sink failure must never mask the health-check reason.
    try {
      await deps.events.emitAppEvent({
        type: APP_DEPLOY_HEALTH_CHECK_FAILED,
        appId: input.appId,
        taskId: version.taskId,
        data: { versionId: input.versionId, slot },
      });
    } catch {
      // swallow — the DeployFailedError below is the retrievable reason
    }
    throw new DeployFailedError('health-check', cause ? { cause } : undefined);
  }

  // The sole traffic-moving commit — last mutating step (AC1).
  try {
    await writeAppRegistryRow(
      input.appHost,
      (c) => ({
        app_host: input.appHost,
        app_id: input.appId,
        live_slot: slot,
        is_public: c?.is_public ?? false,
        revocation_generation: c?.revocation_generation ?? 0,
        deployed_version_id: input.versionId,
      }),
      deps.registry,
    );
  } catch (err) {
    throw new DeployFailedError('write-registry', { cause: err });
  }

  // Best-effort reachability event — makes SM-1 computable from the event stream.
  // reachable is always true here: this line is reached only after the probe passed
  // and the CAS cutover committed; failure paths emit APP_DEPLOY_HEALTH_CHECK_FAILED
  // (or throw) instead, so SM-1 is the ratio of APP_DEPLOYED to failure events.
  // Mirrors the APP_DEPLOY_HEALTH_CHECK_FAILED emit above: a sink failure must
  // never mask a successful deploy.
  try {
    await deps.events.emitAppEvent({
      type: APP_DEPLOYED,
      appId: input.appId,
      taskId: version.taskId,
      data: { versionId: input.versionId, liveSlot: slot, reachable: true },
    });
  } catch {
    // swallow — an event-sink failure must never mask a successful deploy
  }

  return { status: 'deployed', liveSlot: slot };
}
