/**
 * Provider payload contracts — Story DW-60.
 *
 * One definition of "a payload the provider will accept", enforced by both the real
 * adapter and the in-memory fake. The fake used to gate each call and return a canned
 * value without inspecting a field, so a payload the account rejects outright passed
 * every unit test. Four defects reached a real account that way: a 64-char asset hash,
 * a hash used as the asset path, a completion token read as a string, and an upload
 * that dropped the compatibility flags the App was built with.
 *
 * These assertions encode only what the provider itself enforces, derived from the
 * request each adapter method actually issues. An assertion tighter than the provider
 * is its own defect — it would reject payloads the account accepts.
 */

import { slotScriptName } from './slots.js';
import type {
  ApplyMigrationParams,
  DeleteAppParams,
  OpenUploadSessionParams,
  ProbeHealthParams,
  ProvisionBucketParams,
  ProvisionDatabaseParams,
  ReadMigrationLedgerParams,
  UploadAssetsParams,
  UploadScriptParams,
} from './provider-api.port.js';

/** Worker script and D1 database names: lowercase, alphanumeric plus - and _, <= 63 chars. */
const RESOURCE_NAME = /^[a-z0-9][a-z0-9_-]{0,62}$/;
/**
 * R2 bucket names: 3–63 chars, lowercase alphanumerics and hyphens, no leading or
 * trailing hyphen. Stricter than RESOURCE_NAME (no underscores, no 1–2 char names),
 * which is why that regex is not reused (verified against Cloudflare's bucket-naming
 * documentation).
 */
const R2_BUCKET_NAME = /^[a-z0-9][a-z0-9-]{1,61}[a-z0-9]$/;
/** Asset manifest hash: SHA-256 truncated to 16 bytes. A 64-char digest is rejected. */
const ASSET_HASH = /^[0-9a-f]{32}$/;
/** Provider resource ids are UUIDs; anything else lands in a URL as a literal. */
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
/** Binding names are exposed on `env`, so they must be valid identifiers. */
const BINDING_NAME = /^[A-Za-z_][A-Za-z0-9_]*$/;
/** Compatibility dates are YYYY-MM-DD; the provider rejects any other shape. */
const COMPAT_DATE = /^\d{4}-\d{2}-\d{2}$/;

const SLOTS = new Set(['a', 'b']);

export class ProviderContractError extends Error {
  constructor(operation: string, detail: string) {
    super(`${operation}: ${detail}`);
    this.name = 'ProviderContractError';
  }
}

function assertSlot(operation: string, slot: string): void {
  if (!SLOTS.has(slot)) {
    throw new ProviderContractError(operation, `slot must be 'a' or 'b', got "${slot}"`);
  }
}

/**
 * The script name is derived, not supplied, so this validates the derivation's output.
 * A appId that produces an invalid script name fails here rather than as an opaque
 * provider error on the request that uses it.
 */
function assertScriptSlot(operation: string, appId: string, slot: string): void {
  assertSlot(operation, slot);
  const scriptName = slotScriptName(appId, slot as 'a' | 'b');
  if (!RESOURCE_NAME.test(scriptName)) {
    throw new ProviderContractError(
      operation,
      `appId "${appId}" derives the invalid script name "${scriptName}"`,
    );
  }
}

export function assertOpenUploadSessionContract(params: OpenUploadSessionParams): void {
  assertScriptSlot('openUploadSession', params.appId, params.slot);
}

export function assertUploadAssetsContract(params: UploadAssetsParams): void {
  for (const [path, asset] of Object.entries(params.assets)) {
    if (!path.startsWith('/')) {
      throw new ProviderContractError(
        'uploadAssets',
        `asset key "${path}" must be a publish path rooted with '/'`,
      );
    }
    if (!ASSET_HASH.test(asset.hash)) {
      throw new ProviderContractError(
        'uploadAssets',
        `asset "${path}" hash must be 32 lowercase hex chars, got ${asset.hash.length}`,
      );
    }
  }
}

export function assertUploadScriptContract(params: UploadScriptParams): void {
  assertSlot('uploadScript', params.slot);
  if (params.script.length === 0) {
    throw new ProviderContractError('uploadScript', 'script body is empty');
  }
  if (params.disableDirectSubdomain !== true) {
    throw new ProviderContractError('uploadScript', 'disableDirectSubdomain must be true (AD-11)');
  }
  for (const binding of params.bindings) {
    if (!BINDING_NAME.test(binding.name)) {
      throw new ProviderContractError(
        'uploadScript',
        `binding name "${binding.name}" is not a valid identifier`,
      );
    }
    switch (binding.type) {
      case 'd1':
        if (!UUID.test(binding.id)) {
          throw new ProviderContractError(
            'uploadScript',
            `binding "${binding.name}" id must be a provider UUID, got "${binding.id}"`,
          );
        }
        break;
      case 'r2_bucket':
        if (!R2_BUCKET_NAME.test(binding.bucketName)) {
          throw new ProviderContractError(
            'uploadScript',
            `binding "${binding.name}" bucket name "${binding.bucketName}" breaks R2's rule — ` +
              '3–63 lowercase alphanumerics and hyphens, no leading or trailing hyphen',
          );
        }
        break;
    }
  }
  if (params.runtime) {
    if (!COMPAT_DATE.test(params.runtime.compatibilityDate)) {
      throw new ProviderContractError(
        'uploadScript',
        `compatibilityDate must be YYYY-MM-DD, got "${params.runtime.compatibilityDate}"`,
      );
    }
    for (const flag of params.runtime.compatibilityFlags) {
      if (!flag) throw new ProviderContractError('uploadScript', 'compatibility flag is empty');
    }
  }
}

export function assertProvisionBucketContract(params: ProvisionBucketParams): void {
  // Mirrors the name the adapter derives: `app-${appId}`. Checked against R2's own
  // rule, not RESOURCE_NAME — a appId that is not lowercase hex would derive a name
  // the provider rejects, and this fails it by name before any provider call.
  const name = `app-${params.appId}`;
  if (!R2_BUCKET_NAME.test(name)) {
    throw new ProviderContractError(
      'provisionBucket',
      `appId "${params.appId}" derives the invalid bucket name "${name}" — R2 bucket ` +
        'names are 3–63 lowercase alphanumerics and hyphens, no leading or trailing hyphen',
    );
  }
}

export function assertProvisionDatabaseContract(params: ProvisionDatabaseParams): void {
  // Mirrors the name the adapter sends: `app-${appId}`.
  const name = `app-${params.appId}`;
  if (!RESOURCE_NAME.test(name)) {
    throw new ProviderContractError(
      'provisionDatabase',
      `appId "${params.appId}" derives the invalid database name "${name}"`,
    );
  }
  if (!params.organizationId) {
    throw new ProviderContractError('provisionDatabase', 'organizationId is required');
  }
}

export function assertApplyMigrationContract(params: ApplyMigrationParams): void {
  if (!UUID.test(params.databaseId)) {
    // Without this the request URL becomes /d1/database/undefined/query, which the
    // provider answers with an error naming nothing useful.
    throw new ProviderContractError(
      'applyMigration',
      `databaseId must be a provider UUID, got "${params.databaseId}"`,
    );
  }
  if (!params.sql.trim()) {
    throw new ProviderContractError('applyMigration', `migration ${params.ordinal} has empty SQL`);
  }
  if (!Number.isInteger(params.ordinal) || params.ordinal < 0) {
    throw new ProviderContractError('applyMigration', `ordinal must be a non-negative integer`);
  }
}

export function assertReadMigrationLedgerContract(params: ReadMigrationLedgerParams): void {
  if (!UUID.test(params.databaseId)) {
    throw new ProviderContractError(
      'readMigrationLedger',
      `databaseId must be a provider UUID, got "${params.databaseId}"`,
    );
  }
}

export function assertProbeHealthContract(params: ProbeHealthParams): void {
  assertSlot('probeHealth', params.slot);
  if (!params.appHost || /[\s/:]/.test(params.appHost)) {
    throw new ProviderContractError(
      'probeHealth',
      `appHost must be a bare hostname, got "${params.appHost}"`,
    );
  }
  if (!params.probeSignature) {
    throw new ProviderContractError('probeHealth', 'probeSignature is required');
  }
  if (!params.appId) {
    throw new ProviderContractError('probeHealth', 'appId is required');
  }
}

export function assertDeleteAppContract(params: DeleteAppParams): void {
  for (const slot of params.slots) assertScriptSlot('deleteApp', params.appId, slot);
  if (params.databaseId !== undefined && !UUID.test(params.databaseId)) {
    throw new ProviderContractError(
      'deleteApp',
      `databaseId must be a provider UUID, got "${params.databaseId}"`,
    );
  }
}
