/**
 * Provider API port — the seam between the deploy/delete pipeline and the
 * Workers-for-Platforms provider. No base URL, endpoint, or credential lives
 * here; those are injected into the real adapter the consuming story builds.
 *
 * Operations seeded from AD-8 (script upload), AD-9 (asset staging — three
 * calls), AD-10 (D1 provision), AD-11 (direct-subdomain disable), AD-15
 * (health probe), AD-18 (delete). Payload shapes are coarse and are refined
 * by the story that first calls each operation.
 */

import { FakeCallController } from './fake-call-controller.js';
import {
  assertApplyMigrationContract,
  assertDeleteAppContract,
  assertOpenUploadSessionContract,
  assertProbeHealthContract,
  assertProvisionBucketContract,
  assertProvisionDatabaseContract,
  assertReadMigrationLedgerContract,
  assertUploadAssetsContract,
  assertUploadScriptContract,
} from './provider-contract.js';

// ---------------------------------------------------------------------------
// Coarse payload types
// ---------------------------------------------------------------------------

export interface OpenUploadSessionParams {
  appId: string;
  slot: string;
}

export interface OpenUploadSessionResult {
  sessionId: string;
}

export interface UploadAssetsParams {
  sessionId: string;
  /**
   * Publish path → { hash, bytes }. The key is the path the asset is served at
   * (rooted with '/'), never the hash: the provider addresses assets by path.
   * The hash is the tenant-salted, 32-hex-char key from buildAssetManifest.
   */
  assets: Record<string, { hash: string; bytes: Uint8Array }>;
}

/**
 * A single binding to attach to the uploaded script.
 * Only declared bindings appear here — ASSETS is always attached by the adapter.
 *
 * A two-member union, not a registry: a third type grows it by one arm and the
 * switches by one case, which is less code than the abstraction that would have
 * anticipated it.
 */
export type AppScriptBinding =
  | {
      type: 'd1';
      name: string;
      /** The D1 database UUID. */
      id: string;
    }
  | {
      type: 'r2_bucket';
      name: string;
      /** The derived bucket name (`app-{appId}`) — R2 addresses buckets by name, not id. */
      bucketName: string;
    };

/** AD-11: disableDirectSubdomain is an architecturally-fixed flag. */
export interface UploadScriptParams {
  sessionId: string;
  slot: string;
  script: Uint8Array;
  disableDirectSubdomain: boolean;
  /** App's declared bindings (ASSETS is always added by the adapter). */
  bindings: AppScriptBinding[];
  /**
   * Compatibility settings the App was built against, from its bundle manifest.
   * Absent for bundles built before the manifest carried them — the adapter then
   * falls back to its injected date and no flags.
   */
  runtime?: { compatibilityDate: string; compatibilityFlags: string[] };
}

export interface ProvisionDatabaseParams {
  appId: string;
  organizationId: string;
}

/**
 * The bucket name is derived (`app-{appId}`), so unlike provisionDatabase there is
 * no result to return and nothing to persist — the DW-24 crash window (provisioned
 * but not recorded) cannot arise.
 */
export interface ProvisionBucketParams {
  appId: string;
}

export interface ProvisionDatabaseResult {
  databaseId: string;
}

export interface ApplyMigrationParams {
  databaseId: string;
  ordinal: number;
  sql: string;
  hash: string;
}

export interface ReadMigrationLedgerParams {
  databaseId: string;
}

/**
 * One row of the platform-owned migration ledger inside an App Database (AD-14).
 *
 * `applying` means a deploy wrote the row and did not return to mark it applied — the
 * migration's outcome is unknown. It is never repaired automatically, because the
 * platform cannot know whether the SQL landed.
 */
export interface MigrationLedgerEntry {
  ordinal: number;
  hash: string;
  status: 'applying' | 'applied';
}

export interface ProbeHealthParams {
  slot: string;
  probeSignature: string;
  /** The deployed edge hostname — the probe GETs the app root over HTTPS. */
  appHost: string;
  /** The App identifier, sent under the Apps probe header. */
  appId: string;
}

export interface ProbeHealthResult {
  ok: boolean;
  /**
   * Why the probe was unhealthy — status and a short body excerpt. Present only
   * when ok is false. Without it a health-check failure names no cause at all and
   * every diagnosis needs a re-run with instrumentation.
   */
  detail?: string;
}

export interface DeleteAppParams {
  appId: string;
  slots: string[];
  databaseId?: string;
}

// ---------------------------------------------------------------------------
// Port interface
// ---------------------------------------------------------------------------

export interface AppProviderApi {
  /** Step 1 of three-call asset flow — open an upload session (AD-9). */
  openUploadSession(params: OpenUploadSessionParams): Promise<OpenUploadSessionResult>;

  /** Step 2 of three-call asset flow — stage asset buckets in the session (AD-9). */
  uploadAssets(params: UploadAssetsParams): Promise<void>;

  /**
   * Step 3 of three-call asset flow — upload script with completion token
   * (AD-8 commit point). Must disable direct provider-subdomain access (AD-11).
   */
  uploadScript(params: UploadScriptParams): Promise<void>;

  /** Provision a per-App D1 database tagged with the organization (AD-10). */
  provisionDatabase(params: ProvisionDatabaseParams): Promise<ProvisionDatabaseResult>;

  /**
   * Idempotently create the App's derived bucket `app-{appId}` (AD-18). Swallows
   * only the provider's already-exists answer; every other failure propagates.
   */
  provisionBucket(params: ProvisionBucketParams): Promise<void>;

  /** Apply one migration via the provider HTTP data API (AD-15). */
  applyMigration(params: ApplyMigrationParams): Promise<void>;

  /**
   * Read the platform-owned migration ledger (AD-14). Creates the ledger table if it does
   * not exist, so it is safe against a database provisioned before the ledger existed.
   */
  readMigrationLedger(params: ReadMigrationLedgerParams): Promise<MigrationLedgerEntry[]>;

  /** Health-check the staging slot with a signed probe (AD-15). */
  probeHealth(params: ProbeHealthParams): Promise<ProbeHealthResult>;

  /** Remove App resources: script slots, database, assets (AD-18). */
  deleteApp(params: DeleteAppParams): Promise<void>;

  /**
   * Read back the bindings currently attached to a script slot.
   * Used by the smoke ladder to confirm the upload set the correct bindings.
   */
  getScriptBindings(params: {
    appId: string;
    slot: string;
  }): Promise<Array<{ type: string; name: string; id?: string; bucketName?: string }>>;
}

// ---------------------------------------------------------------------------
// In-memory fake
// ---------------------------------------------------------------------------

/** Deterministic UUID-shaped database id, so fake ids satisfy the real contract. */
function fakeDatabaseUuid(n: number): string {
  const tail = n.toString(16).padStart(12, '0');
  return `00000000-0000-4000-8000-${tail}`;
}

class InMemoryProviderApi implements AppProviderApi {
  private sessionCounter = 0;
  private dbCounter = 0;
  /**
   * databaseId -> ordinal -> entry. Modelled rather than stubbed: apply-once is the
   * property Story 5.11 adds, and a fake that accepted any applyMigration could not tell
   * a correct deploy from one that re-runs every migration (DW-60).
   */
  private readonly ledgers = new Map<string, Map<number, MigrationLedgerEntry>>();
  /**
   * Created bucket names. Modelled rather than stubbed for the same reason as the
   * ledger: the idempotent create (a second provision of the same name succeeds and
   * creates nothing) is the property the deploy pipeline relies on, and in-memory
   * state is the one thing a fake can hold faithfully.
   */
  private readonly buckets = new Set<string>();

  constructor(readonly controller: FakeCallController) {}

  openUploadSession(params: OpenUploadSessionParams): Promise<OpenUploadSessionResult> {
    assertOpenUploadSessionContract(params);
    return this.controller.gate('openUploadSession', [params], () => ({
      sessionId: `session-${++this.sessionCounter}`,
    }));
  }

  uploadAssets(params: UploadAssetsParams): Promise<void> {
    assertUploadAssetsContract(params);
    return this.controller.gate('uploadAssets', [params], () => undefined);
  }

  uploadScript(params: UploadScriptParams): Promise<void> {
    assertUploadScriptContract(params);
    return this.controller.gate('uploadScript', [params], () => undefined);
  }

  provisionDatabase(params: ProvisionDatabaseParams): Promise<ProvisionDatabaseResult> {
    assertProvisionDatabaseContract(params);
    // A provider-shaped UUID, not `db-app-1-1`. The fake's *returns* have to look
    // like the provider's too: a caller that threads this id into applyMigration or
    // deleteApp is exercising the real contract only if the id has the real shape.
    return this.controller.gate('provisionDatabase', [params], () => ({
      databaseId: fakeDatabaseUuid(++this.dbCounter),
    }));
  }

  // async for the same reason as readMigrationLedger below: the contract assert
  // throws synchronously on a malformed appId.
  async provisionBucket(params: ProvisionBucketParams): Promise<void> {
    assertProvisionBucketContract(params);
    return this.controller.gate('provisionBucket', [params], () => {
      // Create-and-swallow-already-exists: adding a present member is a no-op,
      // which is exactly the real adapter's contract.
      this.buckets.add(`app-${params.appId}`);
      return undefined;
    });
  }

  applyMigration(params: ApplyMigrationParams): Promise<void> {
    assertApplyMigrationContract(params);
    return this.controller.gate('applyMigration', [params], () => {
      const ledger = this.ledgers.get(params.databaseId) ?? new Map<number, MigrationLedgerEntry>();
      if (ledger.has(params.ordinal)) {
        // The real ledger's PRIMARY KEY refuses this. Deploy filters applied ordinals
        // before calling, so reaching here means the filter is wrong — which is exactly
        // what this fake now catches without an account.
        throw new Error(
          `migration ledger already holds ordinal ${params.ordinal} for database ${params.databaseId}`,
        );
      }
      ledger.set(params.ordinal, {
        ordinal: params.ordinal,
        hash: params.hash,
        status: 'applied',
      });
      this.ledgers.set(params.databaseId, ledger);
      return undefined;
    });
  }

  // async: the assert below throws synchronously on a bad databaseId, and only an
  // `async` method turns that into a rejected promise instead of a thrown call
  // expression (the other fake methods get away without it because their contract
  // checks reject only shapes the deploy pipeline never passes them).
  async readMigrationLedger(params: ReadMigrationLedgerParams): Promise<MigrationLedgerEntry[]> {
    assertReadMigrationLedgerContract(params);
    return this.controller.gate('readMigrationLedger', [params], () =>
      [...(this.ledgers.get(params.databaseId)?.values() ?? [])].sort(
        (a, b) => a.ordinal - b.ordinal,
      ),
    );
  }

  probeHealth(params: ProbeHealthParams): Promise<ProbeHealthResult> {
    assertProbeHealthContract(params);
    return this.controller.gate('probeHealth', [params], () => ({ ok: true }));
  }

  deleteApp(params: DeleteAppParams): Promise<void> {
    assertDeleteAppContract(params);
    return this.controller.gate('deleteApp', [params], () => undefined);
  }

  getScriptBindings(params: {
    appId: string;
    slot: string;
  }): Promise<Array<{ type: string; name: string }>> {
    return this.controller.gate('getScriptBindings', [params], () => []);
  }
}

// ---------------------------------------------------------------------------
// Factory
// ---------------------------------------------------------------------------

export function createInMemoryProviderApi(): {
  provider: AppProviderApi;
  controller: FakeCallController;
} {
  const controller = new FakeCallController();
  return { provider: new InMemoryProviderApi(controller), controller };
}
