import { MalformedBundleError } from './errors.js';
import type { BundleEntry } from './validate.js';

// ponytail: minimal length-framed container; standard tar/zip can replace this if AD-9
// object-storage archiving needs an interoperable format — the codec is the sole swap point.

/** Archive magic bytes: "MFGP" */
const MAGIC = new Uint8Array([0x4d, 0x46, 0x47, 0x50]);
const FORMAT_VERSION = 0x01;
/** Header: 4 magic + 1 version = 5 bytes. */
const HEADER_SIZE = 5;

const enc = new TextEncoder();
// fatal: reject invalid UTF-8 in a path rather than yielding U+FFFD — the reader is
// the (future) server's untrusted-archive parse boundary (AD-13).
const dec = new TextDecoder('utf-8', { fatal: true });

/**
 * Serialize bundle entries to a deterministic MFGPACK binary archive.
 *
 * Format: magic(4) | version(1) | entry_count(uint32 BE) |
 *         for each entry: path_len(uint32 BE) | path(UTF-8) | content_len(uint32 BE) | content(bytes)
 *
 * Entries are sorted by path before framing (determinism). Content is stored as raw bytes (binary-safe).
 */
export function writeBundleArchive(entries: BundleEntry[]): Uint8Array {
  const sorted = [...entries].sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
  const pathBytes = sorted.map((e) => enc.encode(e.path));
  const contentBytes = sorted.map((e) =>
    typeof e.content === 'string' ? enc.encode(e.content) : e.content,
  );

  let size = HEADER_SIZE + 4; // header + entry count
  for (let i = 0; i < sorted.length; i++) {
    size += 4 + pathBytes[i].length + 4 + contentBytes[i].length;
  }

  const buf = new Uint8Array(size);
  const view = new DataView(buf.buffer);
  let off = 0;

  buf.set(MAGIC, off);
  off += 4;
  buf[off++] = FORMAT_VERSION;
  view.setUint32(off, sorted.length, false);
  off += 4;

  for (let i = 0; i < sorted.length; i++) {
    const pb = pathBytes[i];
    const cb = contentBytes[i];
    view.setUint32(off, pb.length, false);
    off += 4;
    buf.set(pb, off);
    off += pb.length;
    view.setUint32(off, cb.length, false);
    off += 4;
    buf.set(cb, off);
    off += cb.length;
  }

  return buf;
}

/**
 * Deserialize a MFGPACK archive produced by writeBundleArchive.
 * Content is returned as Uint8Array (binary-safe; callers decode as needed).
 *
 * Throws MalformedBundleError on:
 * - bad or missing magic bytes
 * - unsupported version byte
 * - truncated data at any point in the stream
 */
export function readBundleArchive(bytes: Uint8Array): BundleEntry[] {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  let off = 0;

  function need(n: number): void {
    if (off + n > bytes.length) {
      throw new MalformedBundleError('archive is truncated');
    }
  }

  need(HEADER_SIZE + 4);

  for (let i = 0; i < 4; i++) {
    if (bytes[off + i] !== MAGIC[i]) {
      throw new MalformedBundleError('archive has invalid magic bytes');
    }
  }
  off += 4;

  const version = bytes[off++];
  if (version !== FORMAT_VERSION) {
    throw new MalformedBundleError(
      `archive version ${version} is not supported; expected ${FORMAT_VERSION}`,
    );
  }

  const count = view.getUint32(off, false);
  off += 4;

  const entries: BundleEntry[] = [];
  for (let i = 0; i < count; i++) {
    need(4);
    const pathLen = view.getUint32(off, false);
    off += 4;
    if (pathLen === 0) {
      throw new MalformedBundleError('archive entry has an empty path');
    }
    need(pathLen);
    let path: string;
    try {
      path = dec.decode(bytes.subarray(off, off + pathLen));
    } catch {
      throw new MalformedBundleError('archive entry path is not valid UTF-8');
    }
    off += pathLen;
    need(4);
    const contentLen = view.getUint32(off, false);
    off += 4;
    need(contentLen);
    // Always copy: `bytes.slice` aliases the input when `bytes` is a Node Buffer
    // (Buffer.prototype.slice === subarray), which would let callers see later mutations
    // of the source buffer. `new Uint8Array(subarray)` copies for both Buffer and Uint8Array.
    const content = new Uint8Array(bytes.subarray(off, off + contentLen));
    off += contentLen;
    entries.push({ path, content });
  }

  // Reject trailing bytes after the last declared entry: a shared codec must not
  // accept smuggled/appended data a stricter reader would reject (AD-13 "never differ on format").
  if (off !== bytes.length) {
    throw new MalformedBundleError('archive has trailing bytes after the last entry');
  }

  return entries;
}
