/**
 * AppRegistrationStore — the Mongo-facing seam for App lifecycle.
 * Shared by api (AppsRepository) and worker (app activities) without importing either.
 */

export interface AppRecord {
  appId: string;
  orgId: string;
  appSlug: string;
  appName: string;
  creatorMembershipId: string;
  workspaceId: string;
  /** Exact workspace sharing projection; absent on legacy records. */
  sharedWorkspaceIds?: string[];
  taskId: string;
  createdAt: Date;
  /** Set once when the bundle declares a database and the provider provisions it. */
  databaseId?: string;
  /**
   * Set when the App has been tombstoned and provider cleanup is running or pending.
   * `findApp` deliberately still returns these — destroy and deploy both need the record —
   * so any caller that acts on an App (publishing to it, restoring it) must check this
   * itself. `listAppsForCreator` already excludes them.
   */
  deletingSince?: Date;
}

export interface CreateAppInput {
  appId: string;
  orgId: string;
  appSlug: string;
  appName: string;
  creatorMembershipId: string;
  workspaceId: string;
  taskId: string;
}

/**
 * Persisted marker for an App being destroyed. Holds the slug + org-host-label
 * reservation until all resources are confirmed gone and `deleteApp` finalizes.
 */
export interface AppTombstone {
  appId: string;
  orgId: string;
  appSlug: string;
  orgHostLabel: string;
  appHost: string;
  databaseId?: string;
}

export interface AppRegistrationStore {
  /** Returns the set of existing slugs for an org (used as the isTaken set). */
  listSlugs(orgId: string): Promise<string[]>;
  /** True if the slug is already taken in this org (best-effort pre-filter). */
  isSlugTaken(orgId: string, slug: string): Promise<boolean>;
  /**
   * Insert the app record. Throws SlugCollisionError on slug duplicate-key.
   * Idempotent: a retry with the same appId returns the existing record without throwing.
   */
  insertApp(record: CreateAppInput): Promise<AppRecord>;
  /** Delete the app record by appId. No-op if absent. */
  deleteApp(appId: string): Promise<void>;
  /** Return the current org host label, or null if not yet set. */
  getOrgHostLabel(orgId: string): Promise<string | null>;
  /**
   * Conditionally set the org host label only if none is currently set.
   * Returns true if THIS call set it; false if one was already set (race loser).
   */
  allocateOrgHostLabel(orgId: string, label: string): Promise<boolean>;
  /**
   * Release the org host label only if the stored value still equals `label`.
   * No-op if absent or if the stored value differs.
   */
  releaseOrgHostLabel(orgId: string, label: string): Promise<void>;
  /** Return the app record by appId, or null. */
  findApp(appId: string): Promise<AppRecord | null>;
  /**
   * Persist the provider-returned databaseId on the app record.
   * Set-if-unset: first write wins; a retry with the same id is a no-op.
   */
  setAppDatabaseId(appId: string, databaseId: string): Promise<void>;

  /**
   * Mark the app record as deleting (tombstone-first). Idempotent.
   * The record persists (keeping the slug reserved) until `deleteApp` finalizes.
   */
  tombstoneApp(appId: string, appHost: string): Promise<void>;

  /** Return all tombstoned apps (those marked deleting but not yet finalized). */
  listTombstones(): Promise<AppTombstone[]>;
}

/**
 * Creator-scoped App listing. Segregated from AppRegistrationStore because only the
 * worker's agent tools need it — the API's AppsRepository implements the lifecycle port
 * and has its own permission-scoped listing.
 */
export interface AppCreatorLister {
  /**
   * Non-tombstoned Apps created by this membership in this org, newest first, capped at
   * `limit`. Ordered by createdAt descending, tie-broken by appId descending: there is no
   * `updated_at` on the App record, and this matches the API listing's `created_at: -1`.
   *
   * A non-positive `limit` returns no Apps. Implementations must not treat `0` as
   * "unlimited" — Mongo's own `.limit(0)` means exactly that, so it needs guarding.
   */
  listAppsForCreator(
    orgId: string,
    creatorMembershipId: string,
    limit: number,
  ): Promise<AppRecord[]>;
}

/** Thrown by insertApp when the slug is already taken (unique index violation). */
export class SlugCollisionError extends Error {
  constructor(orgId: string, slug: string) {
    super(`Slug "${slug}" is already taken in org "${orgId}"`);
    this.name = 'SlugCollisionError';
  }
}

// ---------------------------------------------------------------------------
// In-memory implementation for tests
// ---------------------------------------------------------------------------

export class InMemoryAppRegistrationStore implements AppRegistrationStore, AppCreatorLister {
  private apps = new Map<string, AppRecord>();
  /** Map from `${orgId}:${slug}` → appId */
  private slugIndex = new Map<string, string>();
  private orgLabels = new Map<string, string>();
  // ponytail: separate map — tombstone state is orthogonal to AppRecord identity
  private tombstoneData = new Map<string, { appHost: string }>();

  async listSlugs(orgId: string): Promise<string[]> {
    const slugs: string[] = [];
    for (const [key] of this.slugIndex) {
      const [kOrg, ...rest] = key.split(':');
      if (kOrg === orgId) slugs.push(rest.join(':'));
    }
    return slugs;
  }

  async isSlugTaken(orgId: string, slug: string): Promise<boolean> {
    return this.slugIndex.has(`${orgId}:${slug}`);
  }

  async insertApp(input: CreateAppInput): Promise<AppRecord> {
    // ponytail: idempotent — same appId is a Temporal retry; return existing record
    const existing = this.apps.get(input.appId);
    if (existing) return existing;
    const key = `${input.orgId}:${input.appSlug}`;
    if (this.slugIndex.has(key)) throw new SlugCollisionError(input.orgId, input.appSlug);
    const record: AppRecord = { ...input, createdAt: new Date() };
    this.apps.set(input.appId, record);
    this.slugIndex.set(key, input.appId);
    return record;
  }

  async deleteApp(appId: string): Promise<void> {
    const record = this.apps.get(appId);
    if (!record) return;
    this.slugIndex.delete(`${record.orgId}:${record.appSlug}`);
    this.apps.delete(appId);
    this.tombstoneData.delete(appId);
  }

  async getOrgHostLabel(orgId: string): Promise<string | null> {
    return this.orgLabels.get(orgId) ?? null;
  }

  async allocateOrgHostLabel(orgId: string, label: string): Promise<boolean> {
    if (this.orgLabels.has(orgId)) return false;
    this.orgLabels.set(orgId, label);
    return true;
  }

  async releaseOrgHostLabel(orgId: string, label: string): Promise<void> {
    if (this.orgLabels.get(orgId) === label) this.orgLabels.delete(orgId);
  }

  async findApp(appId: string): Promise<AppRecord | null> {
    return this.apps.get(appId) ?? null;
  }

  async setAppDatabaseId(appId: string, databaseId: string): Promise<void> {
    // ponytail: set-if-unset — first-write-wins; retry with same id is safe
    const record = this.apps.get(appId);
    if (record && !record.databaseId) record.databaseId = databaseId;
  }

  async tombstoneApp(appId: string, appHost: string): Promise<void> {
    // Idempotent: re-marking an already-tombstoned app is a no-op (uses existing appHost)
    if (!this.tombstoneData.has(appId)) {
      this.tombstoneData.set(appId, { appHost });
    }
    // Also stamp the record, so `findApp` reports the tombstone the way the Mongo store
    // does — `deleting_since` is one column there, not a second collection.
    const record = this.apps.get(appId);
    if (record && !record.deletingSince) record.deletingSince = new Date();
  }

  async listAppsForCreator(
    orgId: string,
    creatorMembershipId: string,
    limit: number,
  ): Promise<AppRecord[]> {
    // Guard before slicing: `.slice(0, -1)` counts back from the end and would return all
    // but the last App, where the Mongo store returns none. Keeps the two in agreement.
    if (limit <= 0) return [];
    return [...this.apps.values()]
      .filter(
        (r) =>
          r.orgId === orgId &&
          r.creatorMembershipId === creatorMembershipId &&
          !this.tombstoneData.has(r.appId),
      )
      .sort(
        (a, b) =>
          b.createdAt.getTime() - a.createdAt.getTime() ||
          (a.appId < b.appId ? 1 : a.appId > b.appId ? -1 : 0),
      )
      .slice(0, limit);
  }

  async listTombstones(): Promise<AppTombstone[]> {
    const result: AppTombstone[] = [];
    for (const [appId, { appHost }] of this.tombstoneData) {
      const record = this.apps.get(appId);
      if (!record) continue; // finalized — skip
      const orgHostLabel = this.orgLabels.get(record.orgId) ?? '';
      result.push({
        appId: record.appId,
        orgId: record.orgId,
        appSlug: record.appSlug,
        orgHostLabel,
        appHost,
        ...(record.databaseId ? { databaseId: record.databaseId } : {}),
      });
    }
    return result;
  }
}
