import { posix } from 'node:path';
import {
  MalformedBundleError,
  DisallowedBundleError,
  MissingMigrationError,
  MigrationRewrittenError,
} from './errors.js';
import { parseManifest, type Manifest, type AppMigration } from './manifest.js';
import {
  WORKER_ENTRY,
  MANIFEST_PATH,
  isManifestPath,
  SOURCE_ROOT,
  SOURCE_META_JOURNAL,
  MIGRATION_META_DIR,
} from './layout.js';

export interface BundleEntry {
  path: string;
  content: string | Uint8Array;
}

export interface PriorAppVersion {
  schemaFingerprint: string;
  migrations: AppMigration[];
}

export interface ValidationContext {
  /** Prior saved App Version, if one exists. Null for a brand-new App. */
  priorAppVersion: PriorAppVersion | null;
  /**
   * Platform-owned values that must not appear byte-exactly in any bundle file:
   * provider account ids, database ids, bucket names, secret values.
   * The check is a byte-exact substring scan — no entropy heuristic (AD-13, AD-13a).
   */
  forbiddenLiterals: string[];
}

export interface ValidationResult {
  manifest: Manifest;
}

function isPathEscape(entryPath: string): boolean {
  if (!entryPath) return true;
  // Backslashes are not valid in bundle paths; reject rather than normalize,
  // so a Windows-style escape like `dist\..\..\x` doesn't slip through posix.normalize.
  if (entryPath.includes('\\')) return true;
  if (posix.isAbsolute(entryPath)) return true;
  const normalized = posix.normalize(entryPath);
  return normalized === '..' || normalized.startsWith('../');
}

function contentAsString(content: string | Uint8Array): string {
  return typeof content === 'string' ? content : new TextDecoder().decode(content);
}

/**
 * Validate an App Bundle. Pure: no filesystem, archive, or network access.
 *
 * Throws:
 * - MalformedBundleError  — structural problem (missing entrypoint, path escape, bad manifest).
 * - DisallowedBundleError — forbidden literal found in a bundle file.
 * - MigrationRewrittenError — a previously saved migration's ordinal now carries a different hash.
 * - MissingMigrationError — schema fingerprint changed (or initial database declared) without a new migration.
 * - MalformedBundleError — bundle carries no entries under SOURCE_ROOT.
 * - MalformedBundleError — an App declares a database with migrations but SOURCE_META_JOURNAL is absent.
 *
 * Returns ValidationResult (with the parsed Manifest) on success.
 */
export function validateBundle(
  entries: BundleEntry[],
  context: ValidationContext,
): ValidationResult {
  // 1. Path-escape check — reject before reading any content.
  for (const entry of entries) {
    if (isPathEscape(entry.path)) {
      throw new MalformedBundleError(`path escapes bundle root: ${entry.path}`);
    }
  }

  // Decode each entry's content once; reused by both the forbidden-literal scan
  // and manifest parsing below.
  const decoded = entries.map((e) => ({ path: e.path, text: contentAsString(e.content) }));

  // 2. Forbidden-literal scan — byte-exact, explicit deny-list (AD-13, AD-13a).
  //
  // SOURCE_ROOT is exempt, and must stay exempt. The rule exists so an App's own *running*
  // code cannot address platform-owned names (AD-14); deploy.ts selects what it uploads by
  // prefix and never serves anything under SOURCE_ROOT, so source is unreachable at runtime.
  // Scanning it does not harden anything — it only rejects legitimate bundles: every Starter
  // vendors the `@mfg-agent/apps` build at `vendor/apps/dist` (ADR-0025) and that build
  // contains MIGRATION_LEDGER_TABLE verbatim, so scanning source refused *every* publish.
  // Do not "tighten" this back. The deployed worker entry and the assets are still scanned,
  // which is where the rule has teeth.
  for (const literal of context.forbiddenLiterals) {
    if (!literal) continue;
    for (const { path, text } of decoded) {
      if (path.startsWith(SOURCE_ROOT)) continue;
      if (text.includes(literal)) {
        throw new DisallowedBundleError(`forbidden literal found in: ${path}`);
      }
    }
  }

  // 3. Worker entrypoint must be present.
  if (!entries.some((e) => e.path === WORKER_ENTRY)) {
    throw new MalformedBundleError(`missing required worker entrypoint: ${WORKER_ENTRY}`);
  }

  // 4. Manifest must be present exactly once and parseable.
  const manifestCount = entries.filter((e) => isManifestPath(e.path)).length;
  if (manifestCount > 1) {
    throw new MalformedBundleError(`duplicate manifest entry: ${MANIFEST_PATH}`);
  }
  const manifestDecoded = decoded.find((e) => isManifestPath(e.path));
  if (!manifestDecoded) {
    throw new MalformedBundleError(`missing bundle manifest: ${MANIFEST_PATH}`);
  }
  let rawJson: unknown;
  try {
    rawJson = JSON.parse(manifestDecoded.text);
  } catch {
    throw new MalformedBundleError(`bundle manifest is not valid JSON: ${manifestDecoded.path}`);
  }
  // parseManifest throws MalformedBundleError on shape violations.
  const manifest = parseManifest(rawJson);

  // 5. Source must be present. A bundle without it produces an App that can never
  // be edited from another chat, and the archive is immutable once written.
  if (!entries.some((e) => e.path.startsWith(SOURCE_ROOT))) {
    throw new MalformedBundleError(
      `bundle carries no source entries under ${SOURCE_ROOT}; the App could not be reopened later`,
    );
  }

  // 6. A declared database with migrations must carry drizzle's snapshots, or the
  // next `drizzle-kit generate` in a restored project has nothing to diff against
  // and re-emits ordinal 0. Checked against the journal only — it is the index
  // drizzle reads, and enumerating per-ordinal snapshots would pull drizzle's file
  // naming into the platform validator.
  if (manifest.database?.schema && manifest.migrations.length > 0) {
    if (!entries.some((e) => e.path === SOURCE_META_JOURNAL)) {
      throw new MalformedBundleError(
        `an App that declares a database with migrations must carry ${SOURCE_META_JOURNAL}; ` +
          "without drizzle's snapshots the next migration cannot be generated. " +
          `Do not delete ${MIGRATION_META_DIR}.`,
      );
    }
  }

  // 7. Schema / migration enforcement (AD-13, AD-14).
  const { priorAppVersion } = context;

  if (priorAppVersion === null) {
    // New app: a declared App Database with non-empty schema requires at least one migration.
    if (manifest.database?.schema && manifest.migrations.length === 0) {
      throw new MissingMigrationError(
        'app declares a database schema but provides no initial migration; ' +
          'add a migration for the initial schema',
      );
    }
  } else {
    // A migration is immutable once saved (AD-14, DW-4). Checked before the
    // fingerprint rule so a rewrite reports as a rewrite rather than as a missing
    // migration, which would send the agent to the wrong fix.
    const priorHashes = new Map(priorAppVersion.migrations.map((m) => [m.ordinal, m.hash]));
    for (const m of manifest.migrations) {
      const priorHash = priorHashes.get(m.ordinal);
      if (priorHash !== undefined && priorHash !== m.hash) {
        throw new MigrationRewrittenError(
          `migration ${m.ordinal} was already saved with different content; migrations are ` +
            'immutable once saved — add a new migration for the change instead of editing ' +
            'this one',
        );
      }
    }

    // Existing app: fingerprint change requires at least one new migration.
    if (manifest.schemaFingerprint !== priorAppVersion.schemaFingerprint) {
      const priorOrdinals = new Set(priorAppVersion.migrations.map((m) => m.ordinal));
      const hasNewMigration = manifest.migrations.some((m) => !priorOrdinals.has(m.ordinal));
      if (!hasNewMigration) {
        throw new MissingMigrationError(
          'schema fingerprint changed but no new migration is present; ' +
            'add a migration for the schema change',
        );
      }
    }
  }

  return { manifest };
}
