/**
 * Destroy domain orchestrator — Story 2.16.
 *
 * Pure function over injected ports; no credentials, no HTTP, no Mongo.
 * Tombstone-first / finalize-last: a crash at any middle step leaves a
 * tombstone (slug reserved), never a freed slug before resources are gone.
 * Every removal is no-op-if-absent so a re-drive or reconciliation re-run
 * is safe under retry.
 */

import type { AppProviderApi } from './provider-api.port.js';
import type { AppObjectStore } from './object-store.port.js';
import type { AppRegistryStore } from './registry.js';
import type { AppVersionStore } from './app-version.js';
import type { AppRegistrationStore, AppTombstone } from './registration.js';
import type { AppAuthorizationPort } from './authorization.port.js';
import type { AppEventSink } from './app-events.js';
import { APP_DESTROYED } from './app-events.js';
import { DestroyFailedError } from './errors.js';

export interface DestroyAppDeps {
  appStore: AppRegistrationStore;
  provider: AppProviderApi;
  registry: AppRegistryStore;
  objectStore: AppObjectStore;
  versionStore: AppVersionStore;
  authz: AppAuthorizationPort;
  events: AppEventSink;
}

export interface DestroyAppInput {
  appId: string;
  appHost: string;
  taskId: string;
}

export type DestroyAppResult = { status: 'destroyed' } | { status: 'already-deleted' };

/**
 * Remove all resources owned by an app and finalize the tombstone.
 * Shared by destroyApp (direct call) and reconcileAppTombstones (re-drive).
 * Each step is no-op-if-absent so partial re-drives are safe.
 */
async function cleanupAndFinalize(deps: DestroyAppDeps, tombstone: AppTombstone): Promise<void> {
  // One provider call removes script slots (both fixed slots), database, and assets (AD-18).
  try {
    await deps.provider.deleteApp({
      appId: tombstone.appId,
      slots: ['a', 'b'],
      ...(tombstone.databaseId ? { databaseId: tombstone.databaseId } : {}),
    });
  } catch (err) {
    throw new DestroyFailedError('delete-provider', { cause: err });
  }

  // Remove each archived version's object-store entry, then remove all version records.
  let versions: Awaited<ReturnType<(typeof deps.versionStore)['listAppVersions']>>;
  try {
    versions = await deps.versionStore.listAppVersions(tombstone.appId);
  } catch (err) {
    throw new DestroyFailedError('list-versions', { cause: err });
  }
  for (const version of versions) {
    try {
      await deps.objectStore.delete(version.archiveKey);
    } catch (err) {
      throw new DestroyFailedError('delete-archive', { cause: err });
    }
    if (version.thumbnailKey) {
      try {
        await deps.objectStore.delete(version.thumbnailKey);
      } catch (err) {
        throw new DestroyFailedError('delete-thumbnail', { cause: err });
      }
    }
  }
  try {
    await deps.versionStore.deleteAppVersions(tombstone.appId);
  } catch (err) {
    throw new DestroyFailedError('delete-version-records', { cause: err });
  }

  // Remove the registry routing row.
  try {
    await deps.registry.delete(tombstone.appHost);
  } catch (err) {
    throw new DestroyFailedError('delete-registry', { cause: err });
  }

  // Bulk-remove all authz tuples for this app (any relation, any subject).
  try {
    await deps.authz.deleteAllForResource({ objectType: 'app', objectId: tombstone.appId });
  } catch (err) {
    throw new DestroyFailedError('delete-authz', { cause: err });
  }

  // Finalize: delete the app record, freeing the slug reservation.
  // deleteApp is unchanged (create-compensation also uses it) — tombstone/finalize are additive.
  try {
    await deps.appStore.deleteApp(tombstone.appId);
  } catch (err) {
    throw new DestroyFailedError('finalize', { cause: err });
  }
}

export async function destroyApp(
  deps: DestroyAppDeps,
  input: DestroyAppInput,
): Promise<DestroyAppResult> {
  const record = await deps.appStore.findApp(input.appId);
  if (!record) return { status: 'already-deleted' };

  // Build tombstone data from live record before marking as deleting.
  const orgHostLabel = (await deps.appStore.getOrgHostLabel(record.orgId)) ?? '';
  const tombstone: AppTombstone = {
    appId: record.appId,
    orgId: record.orgId,
    appSlug: record.appSlug,
    orgHostLabel,
    appHost: input.appHost,
    ...(record.databaseId ? { databaseId: record.databaseId } : {}),
  };

  // Tombstone first — before any removal. Idempotent on re-drive (no-op if already tombstoned).
  await deps.appStore.tombstoneApp(input.appId, input.appHost);

  await cleanupAndFinalize(deps, tombstone);

  // Best-effort terminal event — mirrors APP_DEPLOYED. A sink failure must
  // never mask a successful destroy.
  try {
    await deps.events.emitAppEvent({
      type: APP_DESTROYED,
      appId: input.appId,
      taskId: input.taskId,
      data: { appId: input.appId },
    });
  } catch {
    // swallow — event-sink failure must not mask a successful destroy
  }

  return { status: 'destroyed' };
}

/**
 * Re-drives cleanup+finalization for every tombstoned app.
 * Never touches an app that has no tombstone — acts only on tombstones.
 */
export async function reconcileAppTombstones(deps: DestroyAppDeps): Promise<void> {
  const tombstones = await deps.appStore.listTombstones();
  for (const tombstone of tombstones) {
    // ponytail: isolate per-tombstone — a poison tombstone must not strand the rest of the queue
    try {
      await cleanupAndFinalize(deps, tombstone);
    } catch {
      // leave tombstone in place for the next reconciliation pass
    }
  }
}
