/**
 * App Registry seam — the D1-facing port for the routing store (Epic 2, Story 2.6).
 *
 * One writer (`writeAppRegistryRow`), one fixed row shape, CAS on `revision`.
 * The real D1 adapter binds at Story 2.7/2.8; this module is the domain seam
 * + in-memory fake, exercisable without credentials.
 */

export type AppSlot = 'a' | 'b';

/**
 * Exactly seven fields — no more, no less. A registry.source.test.ts asserts this.
 */
export interface AppRegistryRow {
  app_host: string;
  app_id: string;
  live_slot: AppSlot;
  is_public: boolean;
  revocation_generation: number;
  deployed_version_id: string;
  revision: number;
}

export interface AppRegistryStore {
  read(appHost: string): Promise<AppRegistryRow | null>;
  /**
   * Apply `nextRow` only if the stored revision matches `expectedRevision`
   * (`null` means no row exists yet). Returns true on success, false on mismatch.
   */
  compareAndSwap(nextRow: AppRegistryRow, expectedRevision: number | null): Promise<boolean>;
  /** Remove the registry row for `appHost`. No-op if absent. */
  delete(appHost: string): Promise<void>;
}

// ---------------------------------------------------------------------------
// Writer — exactly one compareAndSwap __CALL_APP__ in all non-test sources
// ---------------------------------------------------------------------------

/**
 * Read → mutate → set revision → compareAndSwap, retrying until committed.
 *
 * `mutate` receives the current row (or null) and returns all six fields
 * except `revision`. The writer owns `revision`: first write → 1, every
 * subsequent write → current.revision + 1.
 *
 * A losing CAS re-reads and retries — no write is ever lost.
 */
export async function writeAppRegistryRow(
  appHost: string,
  mutate: (current: AppRegistryRow | null) => Omit<AppRegistryRow, 'revision'>,
  store: AppRegistryStore,
): Promise<AppRegistryRow> {
  for (;;) {
    const current = await store.read(appHost);
    const expectedRevision = current?.revision ?? null;
    const next: AppRegistryRow = {
      ...mutate(current),
      app_host: appHost, // writer owns the routing key — read-key always equals write-key
      revision: current === null ? 1 : current.revision + 1,
    };
    // ponytail: single CAS __CALL_APP__ — registry.source.test.ts asserts count === 1
    const ok = await store.compareAndSwap(next, expectedRevision);
    if (ok) return next;
  }
}

// ---------------------------------------------------------------------------
// In-memory fake (data-store seam, no FakeCallController gate)
// ---------------------------------------------------------------------------

export class InMemoryAppRegistry implements AppRegistryStore {
  private rows = new Map<string, AppRegistryRow>();

  async read(appHost: string): Promise<AppRegistryRow | null> {
    return this.rows.get(appHost) ?? null;
  }

  async compareAndSwap(nextRow: AppRegistryRow, expectedRevision: number | null): Promise<boolean> {
    const stored = this.rows.get(nextRow.app_host);
    const storedRevision = stored?.revision ?? null;
    if (storedRevision !== expectedRevision) return false;
    this.rows.set(nextRow.app_host, { ...nextRow });
    return true;
  }

  async delete(appHost: string): Promise<void> {
    this.rows.delete(appHost);
  }
}

export function createInMemoryRegistry(): InMemoryAppRegistry {
  return new InMemoryAppRegistry();
}
