/**
 * App authorization port — the seam between the deploy pipeline and SpiceDB
 * (AD-4, AD-20). Types mirror src/api/src/authorization/authorization.types.ts;
 * this module does NOT import from api.
 *
 * The in-memory fake uses direct-tuple matching only — full permission-graph
 * resolution belongs to the real gRPC adapter the consuming story builds.
 */

import { FakeCallController } from './fake-call-controller.js';

// ---------------------------------------------------------------------------
// Minimal SpiceDB-tuple types
// ---------------------------------------------------------------------------

export interface AuthzSubject {
  objectType: string;
  objectId: string;
}

export interface AuthzRelationship {
  resource: { objectType: string; objectId: string };
  relation: string;
  subject: AuthzSubject;
}

export interface AuthzRelationshipUpdate {
  operation: 'touch' | 'delete';
  relationship: AuthzRelationship;
}

export interface AppSharingFence {
  resource: { objectType: 'app'; objectId: string };
  generation: number;
}

export interface AuthzCheck {
  resource: { objectType: string; objectId: string };
  permission: string;
  subject: AuthzSubject;
}

// ---------------------------------------------------------------------------
// Port interface
// ---------------------------------------------------------------------------

export interface AppAuthorizationPort {
  /** Write one or more subject→resource relationship tuples. */
  writeRelationships(relationships: AuthzRelationship[]): Promise<void>;

  /** Remove one or more subject→resource relationship tuples. */
  deleteRelationships(relationships: AuthzRelationship[]): Promise<void>;

  /** Apply TOUCH and DELETE operations atomically in one authorization transaction. */
  writeRelationshipUpdates(
    updates: AuthzRelationshipUpdate[],
    fence?: AppSharingFence,
  ): Promise<void>;

  /** Atomically replace the prior generation's sharing fence with this generation. */
  installSharingFence(fence: AppSharingFence): Promise<void>;

  /** Return true if the subject holds `permission` on the resource. */
  checkPermission(check: AuthzCheck): Promise<boolean>;

  /**
   * Return the IDs of all resources of `resourceType` where the subject
   * holds `permission`.
   */
  lookupResources(params: {
    resourceType: string;
    permission: string;
    subject: AuthzSubject;
  }): Promise<string[]>;

  /**
   * Remove all authorization tuples for the given resource (any relation,
   * any subject). Used by destroy to bulk-remove all app authz records.
   */
  deleteAllForResource(params: { objectType: string; objectId: string }): Promise<void>;

  /**
   * Return ALL distinct relation names present on the resource — including
   * non-sharing relations (manage, owner, editor, viewer, …). Callers must
   * filter; `deriveSharingLevel` already ignores non-sharing relations and is
   * the canonical consumer of this output.
   */
  listResourceRelations(resource: { objectType: string; objectId: string }): Promise<string[]>;

  /** Return every relationship tuple currently stored for the resource. */
  listResourceRelationships(resource: {
    objectType: string;
    objectId: string;
  }): Promise<AuthzRelationship[]>;
}

// ---------------------------------------------------------------------------
// Tuple key helper
// ---------------------------------------------------------------------------

function tupleKey(
  resourceType: string,
  resourceId: string,
  relation: string,
  subjectType: string,
  subjectId: string,
): string {
  return `${resourceType}:${resourceId}#${relation}@${subjectType}:${subjectId}`;
}

function keyFromRelationship(r: AuthzRelationship): string {
  return tupleKey(
    r.resource.objectType,
    r.resource.objectId,
    r.relation,
    r.subject.objectType,
    r.subject.objectId,
  );
}

// ---------------------------------------------------------------------------
// In-memory fake
// ---------------------------------------------------------------------------

class InMemoryAuthorization implements AppAuthorizationPort {
  // ponytail: direct-tuple matching only; SpiceDB can derive permissions
  // through computed userset / tupleset graph traversal — the gRPC adapter
  // handles that when built. Upgrade path: replace this Set with a real client.
  private tuples = new Set<string>();

  constructor(readonly controller: FakeCallController) {}

  writeRelationships(relationships: AuthzRelationship[]): Promise<void> {
    return this.controller.gate('writeRelationships', [relationships], () => {
      for (const r of relationships) this.tuples.add(keyFromRelationship(r));
    });
  }

  deleteRelationships(relationships: AuthzRelationship[]): Promise<void> {
    return this.controller.gate('deleteRelationships', [relationships], () => {
      for (const r of relationships) this.tuples.delete(keyFromRelationship(r));
    });
  }

  writeRelationshipUpdates(
    updates: AuthzRelationshipUpdate[],
    fence?: AppSharingFence,
  ): Promise<void> {
    return this.controller.gate('writeRelationshipUpdates', [updates], () => {
      if (fence && !this.tuples.has(keyFromRelationship(sharingFenceRelationship(fence)))) {
        throw new Error('App sharing fence rejected the stale relationship update');
      }
      for (const update of updates) {
        const key = keyFromRelationship(update.relationship);
        if (update.operation === 'touch') this.tuples.add(key);
        else this.tuples.delete(key);
      }
    });
  }

  installSharingFence(fence: AppSharingFence): Promise<void> {
    return this.controller.gate('installSharingFence', [fence], () => {
      const prefix = `${fence.resource.objectType}:${fence.resource.objectId}#sharing_fence@`;
      const current = [...this.tuples].filter((key) => key.startsWith(prefix));
      const target = keyFromRelationship(sharingFenceRelationship(fence));
      if (current.includes(target)) return;
      const previous = keyFromRelationship(
        sharingFenceRelationship({ ...fence, generation: fence.generation - 1 }),
      );
      if (
        (fence.generation === 1 && current.length > 0) ||
        (fence.generation > 1 && !current.includes(previous))
      ) {
        throw new Error('App sharing fence rejected a stale rotation');
      }
      for (const key of this.tuples) {
        if (key.startsWith(prefix)) this.tuples.delete(key);
      }
      this.tuples.add(target);
    });
  }

  checkPermission(check: AuthzCheck): Promise<boolean> {
    return this.controller.gate('checkPermission', [check], () => {
      const key = tupleKey(
        check.resource.objectType,
        check.resource.objectId,
        check.permission,
        check.subject.objectType,
        check.subject.objectId,
      );
      return this.tuples.has(key);
    });
  }

  lookupResources(params: {
    resourceType: string;
    permission: string;
    subject: AuthzSubject;
  }): Promise<string[]> {
    return this.controller.gate('lookupResources', [params], () => {
      const prefix = `${params.resourceType}:`;
      const suffix = `#${params.permission}@${params.subject.objectType}:${params.subject.objectId}`;
      const ids: string[] = [];
      for (const key of this.tuples) {
        if (key.startsWith(prefix) && key.endsWith(suffix)) {
          const resourceId = key.slice(prefix.length, key.length - suffix.length);
          ids.push(resourceId);
        }
      }
      return ids;
    });
  }

  deleteAllForResource(params: { objectType: string; objectId: string }): Promise<void> {
    return this.controller.gate('deleteAllForResource', [params], () => {
      const prefix = `${params.objectType}:${params.objectId}#`;
      for (const key of this.tuples) {
        if (key.startsWith(prefix)) this.tuples.delete(key);
      }
    });
  }

  listResourceRelations(resource: { objectType: string; objectId: string }): Promise<string[]> {
    return this.controller.gate('listResourceRelations', [resource], () => {
      const prefix = `${resource.objectType}:${resource.objectId}#`;
      const relations = new Set<string>();
      for (const key of this.tuples) {
        if (key.startsWith(prefix)) {
          const afterHash = key.slice(prefix.length);
          const atIdx = afterHash.indexOf('@');
          if (atIdx !== -1) relations.add(afterHash.slice(0, atIdx));
        }
      }
      return [...relations];
    });
  }

  listResourceRelationships(resource: {
    objectType: string;
    objectId: string;
  }): Promise<AuthzRelationship[]> {
    return this.controller.gate('listResourceRelationships', [resource], () => {
      const prefix = `${resource.objectType}:${resource.objectId}#`;
      return [...this.tuples].flatMap((key) => {
        if (!key.startsWith(prefix)) return [];
        const [relation, subjectKey] = key.slice(prefix.length).split('@', 2);
        const separator = subjectKey?.indexOf(':') ?? -1;
        if (!relation || separator < 0) return [];
        return [
          {
            resource,
            relation,
            subject: {
              objectType: subjectKey.slice(0, separator),
              objectId: subjectKey.slice(separator + 1),
            },
          },
        ];
      });
    });
  }
}

function sharingFenceRelationship(fence: AppSharingFence): AuthzRelationship {
  return {
    resource: fence.resource,
    relation: 'sharing_fence',
    subject: { objectType: 'app_change', objectId: String(fence.generation) },
  };
}

// ---------------------------------------------------------------------------
// Factory
// ---------------------------------------------------------------------------

export function createInMemoryAuthorization(): {
  authz: AppAuthorizationPort;
  controller: FakeCallController;
} {
  const controller = new FakeCallController();
  return { authz: new InMemoryAuthorization(controller), controller };
}
