/// <reference lib="webworker" />
export const PROBE_LABEL = 'mfg-agent:apps-edge:probe:v1';

/** HTTP header carrying the HMAC probe signature. */
export const PROBE_HEADER = 'X-Mfg-Probe';

/** HTTP header carrying the App identifier for probe routing. */
export const PROBE_APP_HEADER = 'X-Mfg-Probe-App';

const enc = new TextEncoder();

/**
 * HKDF-SHA256 subkey under PROBE_LABEL.
 * The raw secret is never used to sign directly — only the derived subkey is.
 */
export async function deriveProbeSubkey(secret: Uint8Array): Promise<CryptoKey> {
  // Copy into a plain ArrayBuffer-backed Uint8Array for WebCrypto compatibility
  const keyData = new Uint8Array(secret) as Uint8Array<ArrayBuffer>;
  const hkdfKey = await crypto.subtle.importKey('raw', keyData, 'HKDF', false, ['deriveKey']);
  return crypto.subtle.deriveKey(
    {
      name: 'HKDF',
      hash: 'SHA-256',
      salt: new Uint8Array(32) as Uint8Array<ArrayBuffer>,
      info: enc.encode(PROBE_LABEL) as Uint8Array<ArrayBuffer>,
    },
    hkdfKey,
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign', 'verify'],
  );
}

/**
 * Builds the HMAC message bound to appHost, slot, and appId.
 * Binding appId prevents a valid signature minted for one App from
 * verifying for another — even if host and slot match (e.g. during a
 * first deploy before a registry row exists).
 */
function buildMessage(appHost: string, slot: string, appId: string): Uint8Array<ArrayBuffer> {
  return enc.encode(`${appHost}:${slot}:${appId}`) as Uint8Array<ArrayBuffer>;
}

function b64encode(buf: ArrayBuffer): string {
  let s = '';
  for (const b of new Uint8Array(buf)) s += String.fromCharCode(b);
  return btoa(s);
}

function b64decode(b64: string): Uint8Array<ArrayBuffer> {
  const s = atob(b64);
  const out = new Uint8Array(s.length) as Uint8Array<ArrayBuffer>;
  for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i);
  return out;
}

/** Mint a probe signature bound to appHost, slot, and appId. */
export async function signProbe(
  secret: Uint8Array,
  appHost: string,
  slot: string,
  appId: string,
): Promise<string> {
  const key = await deriveProbeSubkey(secret);
  return b64encode(await crypto.subtle.sign('HMAC', key, buildMessage(appHost, slot, appId)));
}

/**
 * Verify a probe signature bound to appHost, slot, and appId.
 * Returns false on any failure — never throws.
 * A signature minted for a different host, slot, or appId will not verify.
 */
export async function verifyProbeSignature(
  secret: Uint8Array,
  appHost: string,
  slot: string,
  appId: string,
  signature: string,
): Promise<boolean> {
  try {
    const key = await deriveProbeSubkey(secret);
    return crypto.subtle.verify(
      'HMAC',
      key,
      b64decode(signature),
      buildMessage(appHost, slot, appId),
    );
  } catch {
    return false;
  }
}
