/**
 * changeAppSharing domain orchestrator — Story 3.4.
 *
 * Pure function over injected ports; no credentials, no HTTP, no Temporal.
 *
 * Direction-dependent ordering — the narrow side goes first, always:
 * - Narrowing: a SpiceDB `revoking` wildcard denies fresh authorization, then the
 *   registry turns off the public gate and bumps the cookie generation. One atomic
 *   SpiceDB update installs the target, removes stale grants, and clears the deny.
 *   Any partial failure therefore stays fail-closed and is safe to retry.
 * - Widening: SpiceDB first, then the registry row. Granting before the coarse
 *   gate opens never exposes more than intended.
 *
 * Every transition first persists a Mongo write-ahead target claim. Only its
 * owner snapshots the current state and durably prepares the direction and fixed
 * target generation before any side effect. Inline retries and the API recovery
 * poller can prepare an interrupted claim and replay it without losing the target
 * or bumping the generation twice.
 */

import type {
  AppAuthorizationPort,
  AppSharingFence,
  AuthzRelationship,
  AuthzRelationshipUpdate,
} from './authorization.port.js';
import type { AppRegistryRow, AppRegistryStore } from './registry.js';
import { writeAppRegistryRow } from './registry.js';
import {
  SharingLevel,
  APP_RELATIONS,
  deriveSharingLevel,
  isAppSharingRelation,
  isNarrowing,
  sharingLevelTuples,
} from './sharing.js';

export interface ChangeAppSharingDeps {
  authz: AppAuthorizationPort;
  registry: AppRegistryStore;
  changes: AppSharingChangeStore;
}

export interface ChangeAppSharingInput {
  appId: string;
  appHost: string;
  membershipId: string;
  level: SharingLevel;
  orgId: string;
  workspaceIds: string[];
}

/** Mongo-backed target claim before direction and generation are prepared. */
export interface AppSharingChangeClaim extends ChangeAppSharingInput {
  changeId: string;
  prepared: false;
}

export interface PreparedAppSharingChange extends ChangeAppSharingInput {
  changeId: string;
  prepared: true;
  targetGeneration: number;
  narrowed: boolean;
}

export type AppSharingChangeIntent = AppSharingChangeClaim | PreparedAppSharingChange;

export interface AppSharingChangeStore {
  getPending(appId: string): Promise<AppSharingChangeIntent | null>;
  begin(intent: AppSharingChangeClaim): Promise<AppSharingChangeIntent>;
  acquireReplay(
    appId: string,
    changeId: string,
    ownerId: string,
    now: Date,
    expiresAt: Date,
  ): Promise<boolean>;
  renewReplay(
    appId: string,
    changeId: string,
    ownerId: string,
    now: Date,
    expiresAt: Date,
  ): Promise<boolean>;
  prepare(intent: PreparedAppSharingChange, ownerId: string): Promise<AppSharingChangeIntent>;
  complete(appId: string, changeId: string, ownerId: string): Promise<boolean>;
  releaseReplay(appId: string, changeId: string, ownerId: string): Promise<void>;
}

export class AppSharingChangeReplayBusyError extends Error {
  constructor() {
    super('App sharing change is already being replayed');
    this.name = 'AppSharingChangeReplayBusyError';
  }
}

export type ChangeAppSharingResult =
  | {
      status: 'ok';
      level: SharingLevel;
      isPublic: boolean;
      revocationGeneration: number;
      narrowed: boolean;
    }
  | {
      status: 'refused';
      reason:
        | 'not-manager'
        | 'organization-admin-required'
        | 'not-deployed'
        | 'app-mismatch'
        | 'change-in-progress';
    };

export async function changeAppSharing(
  deps: ChangeAppSharingDeps,
  input: ChangeAppSharingInput,
): Promise<ChangeAppSharingResult> {
  const target = { ...input, workspaceIds: [...input.workspaceIds].sort() };
  // (1) authz gate — only app#manage may change sharing
  const canManage = await deps.authz.checkPermission({
    resource: { objectType: 'app', objectId: target.appId },
    permission: 'manage',
    subject: { objectType: 'membership', objectId: target.membershipId },
  });
  if (!canManage) return { status: 'refused', reason: 'not-manager' };

  const pending = await deps.changes.getPending(target.appId);
  if (pending) {
    if (!sameTarget(pending, target)) {
      return { status: 'refused', reason: 'change-in-progress' };
    }
    let resumed: Awaited<ReturnType<typeof resumeAppSharingChange>>;
    try {
      resumed = await resumeAppSharingChange(deps, pending);
    } catch (error) {
      if (error instanceof AppSharingChangeReplayBusyError) {
        return { status: 'refused', reason: 'change-in-progress' };
      }
      throw error;
    }
    return resultFromRow(target.level, resumed.row, resumed.intent.narrowed);
  }

  if (target.level === SharingLevel.Organization) {
    const canManageOrganization = await deps.authz.checkPermission({
      resource: { objectType: 'org', objectId: target.orgId },
      permission: 'manage',
      subject: { objectType: 'membership', objectId: target.membershipId },
    });
    if (!canManageOrganization) {
      return { status: 'refused', reason: 'organization-admin-required' };
    }
  }

  // (2) registry row must exist — do not fabricate live_slot/deployed_version_id
  const current = await deps.registry.read(target.appHost);
  if (!current) return { status: 'refused', reason: 'not-deployed' };
  if (current.app_id !== target.appId) return { status: 'refused', reason: 'app-mismatch' };

  // (3) Claim the target before deriving direction from mutable state. `begin`
  //     is an atomic choose-one operation: a competing target receives the
  //     winner and is refused without touching SpiceDB or the registry.
  const requested: AppSharingChangeClaim = {
    ...target,
    changeId: crypto.randomUUID(),
    prepared: false,
  };
  const intended = await deps.changes.begin(requested);
  if (!sameTarget(intended, requested)) {
    return { status: 'refused', reason: 'change-in-progress' };
  }
  let resumed: Awaited<ReturnType<typeof resumeAppSharingChange>>;
  try {
    resumed = await resumeAppSharingChange(deps, intended);
  } catch (error) {
    if (error instanceof AppSharingChangeReplayBusyError) {
      return { status: 'refused', reason: 'change-in-progress' };
    }
    throw error;
  }
  return resultFromRow(target.level, resumed.row, resumed.intent.narrowed);
}

/** Replays an already-authorized durable intent; deliberately does not re-check manage. */
export async function resumeAppSharingChange(
  deps: ChangeAppSharingDeps,
  intent: AppSharingChangeIntent,
): Promise<{ row: AppRegistryRow; intent: PreparedAppSharingChange }> {
  const ownerId = crypto.randomUUID();
  if (!(await acquireReplay(deps.changes, intent, ownerId))) {
    throw new AppSharingChangeReplayBusyError();
  }
  let completed = false;
  try {
    const prepared = intent.prepared
      ? intent
      : await prepareAppSharingChange(deps, intent, ownerId);
    await renewReplay(deps.changes, prepared, ownerId);
    await reserveRegistryFence(deps.registry, prepared);
    await renewReplay(deps.changes, prepared, ownerId);
    await deps.authz.installSharingFence(sharingFence(prepared));
    let row: AppRegistryRow;
    if (!prepared.narrowed) {
      await renewReplay(deps.changes, prepared, ownerId);
      await applyTargetRelations(deps.authz, prepared, sharingFence(prepared));
      await renewReplay(deps.changes, prepared, ownerId);
      row = await writeTargetRegistryRow(deps.registry, prepared);
    } else {
      const resource = { objectType: 'app', objectId: prepared.appId };
      await renewReplay(deps.changes, prepared, ownerId);
      await deps.authz.writeRelationshipUpdates(
        [
          {
            operation: 'touch',
            relationship: {
              resource,
              relation: APP_RELATIONS.REVOKING,
              subject: { objectType: 'membership', objectId: '*' },
            },
          },
        ],
        sharingFence(prepared),
      );
      await renewReplay(deps.changes, prepared, ownerId);
      row = await writeTargetRegistryRow(deps.registry, prepared);
      await renewReplay(deps.changes, prepared, ownerId);
      await applyTargetRelations(deps.authz, prepared, sharingFence(prepared));
    }

    await renewReplay(deps.changes, prepared, ownerId);
    completed = await deps.changes.complete(prepared.appId, prepared.changeId, ownerId);
    if (!completed) throw new AppSharingChangeReplayBusyError();
    return { row, intent: prepared };
  } finally {
    if (!completed) {
      try {
        await deps.changes.releaseReplay(intent.appId, intent.changeId, ownerId);
      } catch {
        // Recovery can take over after lease expiry if best-effort release fails.
      }
    }
  }
}

async function prepareAppSharingChange(
  deps: ChangeAppSharingDeps,
  claim: AppSharingChangeClaim,
  ownerId: string,
): Promise<PreparedAppSharingChange> {
  await renewReplay(deps.changes, claim, ownerId);
  const current = await deps.registry.read(claim.appHost);
  if (!current) throw new Error('app registry row deleted during sharing change preparation');
  if (current.app_id !== claim.appId) throw new Error('app registry row changed app identity');
  await renewReplay(deps.changes, claim, ownerId);
  const relationships = await deps.authz.listResourceRelationships({
    objectType: 'app',
    objectId: claim.appId,
  });
  const from = current.is_public
    ? SharingLevel.Public
    : deriveSharingLevel(relationships.map(({ relation }) => relation));
  const narrowed =
    isNarrowing(from, claim.level) || removesExistingWorkspaceTarget(from, claim, relationships);
  const candidate: PreparedAppSharingChange = {
    ...claim,
    prepared: true,
    targetGeneration: current.revocation_generation + 1,
    narrowed,
  };
  await renewReplay(deps.changes, claim, ownerId);
  const prepared = await deps.changes.prepare(candidate, ownerId);
  if (prepared.changeId !== claim.changeId || !prepared.prepared) {
    throw new Error('App sharing change claim was replaced during preparation');
  }
  return prepared;
}

function removesExistingWorkspaceTarget(
  from: SharingLevel,
  target: ChangeAppSharingInput,
  relationships: AuthzRelationship[],
): boolean {
  if (from !== SharingLevel.Workspace || target.level !== SharingLevel.Workspace) return false;
  const targetIds = new Set(target.workspaceIds);
  return relationships.some(
    ({ relation, subject }) =>
      (relation === APP_RELATIONS.WORKSPACE_VIEWER ||
        relation === APP_RELATIONS.WORKSPACE_EDITOR) &&
      subject.objectType === 'workspace' &&
      !targetIds.has(subject.objectId),
  );
}

async function acquireReplay(
  store: AppSharingChangeStore,
  intent: AppSharingChangeIntent,
  ownerId: string,
): Promise<boolean> {
  const now = new Date();
  return store.acquireReplay(
    intent.appId,
    intent.changeId,
    ownerId,
    now,
    new Date(now.getTime() + REPLAY_LEASE_MS),
  );
}

async function renewReplay(
  store: AppSharingChangeStore,
  intent: AppSharingChangeIntent,
  ownerId: string,
): Promise<void> {
  const now = new Date();
  const renewed = await store.renewReplay(
    intent.appId,
    intent.changeId,
    ownerId,
    now,
    new Date(now.getTime() + REPLAY_LEASE_MS),
  );
  if (!renewed) throw new AppSharingChangeReplayBusyError();
}

export const APP_SHARING_REPLAY_LEASE_MS = 60_000;
const REPLAY_LEASE_MS = APP_SHARING_REPLAY_LEASE_MS;

async function writeTargetRegistryRow(
  registry: AppRegistryStore,
  intent: PreparedAppSharingChange,
): Promise<AppRegistryRow> {
  return writeAppRegistryRow(
    intent.appHost,
    (current) => {
      if (!current) throw new Error('app registry row deleted during sharing change');
      if (current.app_id !== intent.appId) throw new Error('app registry row changed app identity');
      if (current.revocation_generation !== intent.targetGeneration) {
        throw new Error('App sharing generation fence rejected a stale registry write');
      }
      return {
        ...current,
        is_public: intent.level === SharingLevel.Public,
        revocation_generation: intent.targetGeneration,
      };
    },
    registry,
  );
}

async function reserveRegistryFence(
  registry: AppRegistryStore,
  intent: PreparedAppSharingChange,
): Promise<AppRegistryRow> {
  return writeAppRegistryRow(
    intent.appHost,
    (current) => {
      if (!current) throw new Error('app registry row deleted during sharing fence reservation');
      if (current.app_id !== intent.appId) throw new Error('app registry row changed app identity');
      if (current.revocation_generation > intent.targetGeneration) {
        throw new Error('App sharing generation fence rejected a stale reservation');
      }
      if (current.revocation_generation < intent.targetGeneration - 1) {
        throw new Error('App sharing generation fence is not contiguous');
      }
      return { ...current, revocation_generation: intent.targetGeneration };
    },
    registry,
  );
}

function sharingFence(intent: PreparedAppSharingChange): AppSharingFence {
  return {
    resource: { objectType: 'app', objectId: intent.appId },
    generation: intent.targetGeneration,
  };
}

async function applyTargetRelations(
  authz: AppAuthorizationPort,
  input: ChangeAppSharingInput,
  fence: AppSharingFence,
): Promise<void> {
  const resource = { objectType: 'app', objectId: input.appId };
  const targetTuples = sharingLevelTuples(input.level, input.orgId, input.workspaceIds);
  const targetKeys = new Set(
    targetTuples.map(
      ({ relation, subject }) => `${relation}\u0000${subject.objectType}\u0000${subject.objectId}`,
    ),
  );
  const existing = await authz.listResourceRelationships(resource);
  const revoking: AuthzRelationship = {
    resource,
    relation: APP_RELATIONS.REVOKING,
    subject: { objectType: 'membership', objectId: '*' },
  };
  const updates: AuthzRelationshipUpdate[] = [
    ...targetTuples.map((tuple) => ({
      operation: 'touch' as const,
      relationship: { resource, relation: tuple.relation, subject: tuple.subject },
    })),
    ...existing
      .filter(({ relation, subject }) => {
        const key = `${relation}\u0000${subject.objectType}\u0000${subject.objectId}`;
        return isAppSharingRelation(relation) && !targetKeys.has(key);
      })
      .map((relationship) => ({
        operation: 'delete' as const,
        relationship,
      })),
    { operation: 'delete' as const, relationship: revoking },
  ];
  await authz.writeRelationshipUpdates(updates, fence);
}

function sameTarget(pending: AppSharingChangeIntent, input: ChangeAppSharingInput): boolean {
  return (
    pending.appId === input.appId &&
    pending.appHost === input.appHost &&
    pending.level === input.level &&
    pending.orgId === input.orgId &&
    pending.workspaceIds.length === input.workspaceIds.length &&
    pending.workspaceIds.every((workspaceId, index) => workspaceId === input.workspaceIds[index])
  );
}

function resultFromRow(
  level: SharingLevel,
  row: AppRegistryRow,
  narrowed: boolean,
): ChangeAppSharingResult {
  return {
    status: 'ok',
    level,
    isPublic: row.is_public,
    revocationGeneration: row.revocation_generation,
    narrowed,
  };
}
