/// <reference lib="webworker" />
import { base64urlEncode, base64urlDecode } from './base64url.js';

export const SESSION_LABEL = 'mfg-agent:apps-edge:session:v1';
/** Cookie name — `__Host-` prefix enforces Secure + Path=/ + no Domain. */
export const SESSION_COOKIE_NAME = '__Host-mfg-session';
/** Soft expiry: verify reports softExpired=true, caller should re-mint. */
export const SESSION_SOFT_TTL_SECONDS = 1800; // 30 minutes
/** Hard expiry: verify rejects the cookie entirely. */
export const SESSION_HARD_TTL_SECONDS = 28800; // 8 hours
/** Symmetric clock-skew tolerance for the iat lower bound. */
export const SESSION_SKEW_SECONDS = 60;

const enc = new TextEncoder();
const dec = new TextDecoder();

interface SessionPayload {
  appHost: string;
  user: string;
  org: string;
  workspace: string;
  generation: number;
  iat: number;
}

async function deriveSessionSubkey(secret: Uint8Array): Promise<CryptoKey> {
  const keyData = new Uint8Array(secret) as Uint8Array<ArrayBuffer>;
  const hkdfKey = await crypto.subtle.importKey('raw', keyData, 'HKDF', false, ['deriveKey']);
  return crypto.subtle.deriveKey(
    {
      name: 'HKDF',
      hash: 'SHA-256',
      salt: new Uint8Array(32) as Uint8Array<ArrayBuffer>,
      info: enc.encode(SESSION_LABEL) as Uint8Array<ArrayBuffer>,
    },
    hkdfKey,
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign', 'verify'],
  );
}

/**
 * Mint a session cookie value bound to {appHost, user, generation}.
 * Wire format: base64url(JSON payload) + '.' + base64url(HMAC-SHA256 sig).
 * The generation is read from the registry row by the caller; it is never
 * derived here.
 */
export async function mintSessionCookie(
  secret: Uint8Array,
  opts: { appHost: string; user: string; org: string; workspace: string; generation: number },
  now = Date.now() / 1000,
): Promise<string> {
  const payload: SessionPayload = {
    appHost: opts.appHost,
    user: opts.user,
    org: opts.org,
    workspace: opts.workspace,
    generation: opts.generation,
    iat: Math.floor(now),
  };
  const key = await deriveSessionSubkey(secret);
  const payloadB64 = base64urlEncode(
    enc.encode(JSON.stringify(payload)) as Uint8Array<ArrayBuffer>,
  );
  const sig = await crypto.subtle.sign(
    'HMAC',
    key,
    enc.encode(payloadB64) as Uint8Array<ArrayBuffer>,
  );
  return `${payloadB64}.${base64urlEncode(new Uint8Array(sig))}`;
}

export type SessionVerifyResult =
  | {
      ok: true;
      user: string;
      org: string;
      workspace: string;
      generation: number;
      softExpired: boolean;
    }
  | { ok: false; reason: string };

/**
 * Verify a session cookie value.
 * - Fails if the appHost doesn't match (session isolation).
 * - Fails past the hard TTL.
 * - Succeeds past the soft TTL with softExpired=true (caller should re-mint).
 * - Exposes the generation to the caller for revocation-generation comparison.
 *
 * DW-37 named this function alongside verifyHandoffToken for its catch-all
 * `parse-error`. It is accurate here and stays: this function performs no I/O and
 * injects no store, so the only things that can throw are decode and JSON.parse —
 * both genuinely malformed input. The handoff path was the one with a store behind
 * the catch, and that is where the reason is now separated.
 */
export async function verifySessionCookie(
  secret: Uint8Array,
  value: string,
  opts: { appHost: string },
  now = Date.now() / 1000,
): Promise<SessionVerifyResult> {
  try {
    const dot = value.indexOf('.');
    if (dot === -1) return { ok: false, reason: 'malformed' };
    const payloadB64 = value.slice(0, dot);
    const sigB64 = value.slice(dot + 1);
    if (!payloadB64 || !sigB64) return { ok: false, reason: 'malformed' };

    const key = await deriveSessionSubkey(secret);
    const valid = await crypto.subtle.verify(
      'HMAC',
      key,
      base64urlDecode(sigB64),
      enc.encode(payloadB64) as Uint8Array<ArrayBuffer>,
    );
    if (!valid) return { ok: false, reason: 'signature' };

    const payload = JSON.parse(dec.decode(base64urlDecode(payloadB64))) as SessionPayload;

    // Runtime shape guard — defense-in-depth against mint-side bug or schema drift
    if (
      typeof payload.appHost !== 'string' ||
      typeof payload.user !== 'string' ||
      typeof payload.org !== 'string' ||
      !payload.org ||
      typeof payload.workspace !== 'string' ||
      !payload.workspace ||
      typeof payload.iat !== 'number' ||
      typeof payload.generation !== 'number'
    )
      return { ok: false, reason: 'malformed' };

    // App isolation — a cookie minted for appA is worthless at appB
    if (payload.appHost !== opts.appHost) return { ok: false, reason: 'app-mismatch' };

    const age = now - payload.iat;
    if (age < -SESSION_SKEW_SECONDS) return { ok: false, reason: 'future' };
    if (age > SESSION_HARD_TTL_SECONDS) return { ok: false, reason: 'hard-expired' };

    return {
      ok: true,
      user: payload.user,
      org: payload.org,
      workspace: payload.workspace,
      generation: payload.generation,
      softExpired: age > SESSION_SOFT_TTL_SECONDS,
    };
  } catch {
    return { ok: false, reason: 'parse-error' };
  }
}

/**
 * Build the Set-Cookie header value for the session cookie.
 * Attributes: __Host- prefix, Path=/, Secure, HttpOnly, SameSite=Lax, Max-Age.
 * No Domain attribute — enforced by __Host- prefix semantics.
 */
export function buildSessionSetCookie(value: string, maxAgeSeconds: number): string {
  if (/[;\r\n]/.test(value)) throw new Error('invalid cookie value');
  return `${SESSION_COOKIE_NAME}=${value}; Path=/; Secure; HttpOnly; SameSite=Lax; Max-Age=${maxAgeSeconds}`;
}
