import { MalformedBundleError } from './errors.js';

/** Ordered migration entry recorded in the manifest. Identity = ordinal + hash (AD-14). */
export interface AppMigration {
  ordinal: number;
  hash: string;
}

/**
 * Logical App Database declaration. Contains only the schema entrypoint path(s) used to
 * compute the schemaFingerprint — no provider identifier, connection string, or
 * credential (AD-13a, AD-18). The fingerprint, not this field, is the audit artifact;
 * shipping the schema source as well would duplicate in every archive what the hash
 * already reduces.
 */
export interface AppDatabaseDeclaration {
  /** Comma-separated project-relative schema entrypoint path(s). Non-empty = database declared. */
  schema: string;
}

/**
 * Runtime settings the App was *built* against, carried from the build's generated
 * wrangler config so the platform uploads the script under the same runtime the
 * bundler assumed. Omitting the flags deployed a Worker whose bundle imports node
 * builtins without `nodejs_compat`, which fails at compile with
 * `No such module "crypto"` — the App declared it, packaging read the file, and
 * the deploy invented its own settings instead.
 *
 * Optional: bundles built before this field existed fall back to the adapter's
 * injected compatibility date and no flags.
 */
export interface AppRuntimeDeclaration {
  compatibilityDate: string;
  compatibilityFlags: string[];
}

/**
 * The bundle manifest (`MANIFEST_PATH`). No discriminator field (AD-19).
 *
 * Fields:
 * - schemaVersion  — manifest format version; currently "1".
 * - schemaFingerprint — SHA-256 of the concatenated, newline-normalized Drizzle
 *   schema module sources (see computeSchemaFingerprint).
 * - migrations — ordered list of App Migrations present in this bundle.
 * - database — present only when the App declares an App Database.
 * - bucket — true only when the App declares object storage. Presence-only: the
 *   bucket is `app-{appId}`, derived by the control plane, so unlike `database`
 *   there is nothing further to declare (AD-18, AD-13a).
 * - runtime — compatibility settings the App was built against.
 */
export interface Manifest {
  schemaVersion: string;
  schemaFingerprint: string;
  migrations: AppMigration[];
  database?: AppDatabaseDeclaration;
  bucket?: boolean;
  runtime?: AppRuntimeDeclaration;
}

/**
 * Parse and validate an unknown value as a Manifest.
 * Throws MalformedBundleError if the shape is invalid.
 */
export function parseManifest(json: unknown): Manifest {
  if (typeof json !== 'object' || json === null || Array.isArray(json)) {
    throw new MalformedBundleError('manifest must be a JSON object');
  }

  const obj = json as Record<string, unknown>;

  if (typeof obj['schemaVersion'] !== 'string') {
    throw new MalformedBundleError('manifest.schemaVersion must be a string');
  }
  if (obj['schemaVersion'] !== '1') {
    throw new MalformedBundleError(
      `unsupported manifest schemaVersion: "${obj['schemaVersion']}"; only "1" is supported`,
    );
  }
  if (typeof obj['schemaFingerprint'] !== 'string') {
    throw new MalformedBundleError('manifest.schemaFingerprint must be a string');
  }
  if (obj['schemaFingerprint'] === '') {
    throw new MalformedBundleError('manifest.schemaFingerprint must not be empty');
  }
  if (!Array.isArray(obj['migrations'])) {
    throw new MalformedBundleError('manifest.migrations must be an array');
  }

  const migrations: AppMigration[] = [];
  const seenOrdinals = new Set<number>();
  for (let i = 0; i < obj['migrations'].length; i++) {
    const m = obj['migrations'][i] as Record<string, unknown>;
    if (typeof m !== 'object' || m === null) {
      throw new MalformedBundleError(`manifest.migrations[${i}] must be an object`);
    }
    const ordinal = m['ordinal'];
    // Zero-based: the ordinal is drizzle-kit's own numbering, taken from the migration
    // filename, and its first migration is always `0000_*.sql`. Identity is ordinal +
    // hash (AD-14), so 0 is a real ordinal and not a missing value.
    if (typeof ordinal !== 'number' || !Number.isInteger(ordinal) || ordinal < 0) {
      throw new MalformedBundleError(
        `manifest.migrations[${i}].ordinal must be a non-negative integer`,
      );
    }
    if (seenOrdinals.has(ordinal)) {
      throw new MalformedBundleError(`manifest.migrations has duplicate ordinal: ${ordinal}`);
    }
    seenOrdinals.add(ordinal);
    if (typeof m['hash'] !== 'string') {
      throw new MalformedBundleError(`manifest.migrations[${i}].hash must be a string`);
    }
    if (m['hash'] === '') {
      throw new MalformedBundleError(`manifest.migrations[${i}].hash must not be empty`);
    }
    migrations.push({ ordinal: ordinal as number, hash: m['hash'] as string });
  }

  let database: AppDatabaseDeclaration | undefined;
  if ('database' in obj && obj['database'] !== undefined && obj['database'] !== null) {
    const db = obj['database'] as Record<string, unknown>;
    if (typeof db !== 'object' || Array.isArray(db)) {
      throw new MalformedBundleError('manifest.database must be an object');
    }
    if (typeof db['schema'] !== 'string') {
      throw new MalformedBundleError('manifest.database.schema must be a string');
    }
    database = { schema: db['schema'] as string };
  }

  let bucket: boolean | undefined;
  if (obj['bucket'] !== undefined) {
    if (typeof obj['bucket'] !== 'boolean') {
      throw new MalformedBundleError('manifest.bucket must be a boolean');
    }
    bucket = obj['bucket'];
  }

  let runtime: AppRuntimeDeclaration | undefined;
  if (obj['runtime'] !== undefined) {
    const rt = obj['runtime'];
    if (typeof rt !== 'object' || rt === null || Array.isArray(rt)) {
      throw new MalformedBundleError('manifest.runtime must be an object');
    }
    const rtObj = rt as Record<string, unknown>;
    if (typeof rtObj['compatibilityDate'] !== 'string' || rtObj['compatibilityDate'] === '') {
      throw new MalformedBundleError(
        'manifest.runtime.compatibilityDate must be a non-empty string',
      );
    }
    const flags = rtObj['compatibilityFlags'];
    if (!Array.isArray(flags) || flags.some((f) => typeof f !== 'string')) {
      throw new MalformedBundleError(
        'manifest.runtime.compatibilityFlags must be an array of strings',
      );
    }
    runtime = {
      compatibilityDate: rtObj['compatibilityDate'] as string,
      compatibilityFlags: flags as string[],
    };
  }

  return {
    schemaVersion: obj['schemaVersion'] as string,
    schemaFingerprint: obj['schemaFingerprint'] as string,
    migrations,
    ...(database !== undefined ? { database } : {}),
    ...(bucket !== undefined ? { bucket } : {}),
    ...(runtime !== undefined ? { runtime } : {}),
  };
}
