/// <reference lib="webworker" />

/** URL-safe base64 encode: replaces +→-, /→_, strips padding. */
export function base64urlEncode(buf: Uint8Array): string {
  let s = '';
  for (const b of buf) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
}

/** URL-safe base64 decode: inverse of base64urlEncode. */
export function base64urlDecode(s: string): Uint8Array<ArrayBuffer> {
  const std = s.replace(/-/g, '+').replace(/_/g, '/');
  const rem = std.length % 4;
  const padded = rem === 0 ? std : std + '='.repeat(4 - rem);
  const raw = atob(padded);
  const out = new Uint8Array(raw.length) as Uint8Array<ArrayBuffer>;
  for (let i = 0; i < raw.length; i++) out[i] = raw.charCodeAt(i);
  return out;
}
