// ponytail: RESERVED_HOST_LABELS is a calibration knob — seed covers platform/serving collisions;
// extend as infra hostnames are added (no loop, O(1) lookup).
export const RESERVED_HOST_LABELS = new Set([
  'www',
  'api',
  'app',
  'admin',
  'internal',
  'dispatch',
  'static',
  'assets',
  'health',
  'status',
]);

export const MAX_HOST_LABEL_LENGTH = 63;
export const MAX_ORG_NAME_SLUG_LENGTH = 24;
export const HOST_SUFFIX_LENGTH = 4;

/**
 * Separator joining the App Slug and the Organization Host Label into ONE DNS label.
 * `--` is unambiguous by construction: slugifyHostLabel collapses non-alphanumeric runs to a
 * single hyphen and isValidHostLabel rejects `--`, so neither side can ever contain it.
 */
export const HOST_LABEL_SEPARATOR = '--';

/** Widest Organization Host Label deriveOrgHostLabel can produce: 24 + "-" + 4 = 29. */
const MAX_ORG_HOST_LABEL_LENGTH = MAX_ORG_NAME_SLUG_LENGTH + 1 + HOST_SUFFIX_LENGTH;

/**
 * The composed host is `{slug}--{orgHostLabel}.{servingDomain}` — one DNS label, because
 * Cloudflare Universal SSL only covers a single wildcard level (`*.{servingDomain}`); a
 * nested `{slug}.{orgHostLabel}.{domain}` fails the TLS handshake before any Worker runs.
 * 63 - 2 - 29 = 32 chars available for the App Slug.
 */
export const MAX_APP_SLUG_LENGTH =
  MAX_HOST_LABEL_LENGTH - HOST_LABEL_SEPARATOR.length - MAX_ORG_HOST_LABEL_LENGTH;

// Max base slug length that still leaves room for "-{4-char suffix}": 32 - 1 - 4 = 27
const MAX_BASE_FOR_SUFFIX = MAX_APP_SLUG_LENGTH - 1 - HOST_SUFFIX_LENGTH;

export class InvalidHostLabelError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'InvalidHostLabelError';
  }
}

/**
 * Returns true only for a valid DNS label: lowercase [a-z0-9], single interior hyphens,
 * ≥1 char, ≤63 chars, and not in the reserved set.
 * Total function — never throws.
 */
export function isValidHostLabel(label: string): boolean {
  return (
    label.length >= 1 &&
    label.length <= MAX_HOST_LABEL_LENGTH &&
    /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(label) &&
    !RESERVED_HOST_LABELS.has(label)
  );
}

/**
 * Converts an arbitrary name to a candidate DNS label: lowercase, non-alphanumeric runs
 * collapsed to a single hyphen, leading/trailing hyphens stripped.
 */
export function slugifyHostLabel(name: string): string {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
}

/**
 * Generates a 4-character random suffix from [a-z0-9]. Inject a deterministic replacement
 * in tests via the `randomSuffix` parameter of deriveAppSlug/deriveOrgHostLabel.
 */
export function randomHostSuffix(): string {
  const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let result = '';
  for (let i = 0; i < HOST_SUFFIX_LENGTH; i++) {
    result += chars[Math.floor(Math.random() * chars.length)];
  }
  return result;
}

/**
 * Derives an App Slug that is free according to `isTaken`.
 * Order: base → base-2 … base-9 → base-{randomSuffix()}.
 * The base is truncated to MAX_BASE_FOR_SUFFIX so all variants fit ≤63 chars.
 * Throws InvalidHostLabelError if all bounded candidates are taken.
 */
export function deriveAppSlug(
  name: string,
  isTaken: (slug: string) => boolean,
  randomSuffix: () => string,
): string {
  const base = slugifyHostLabel(name).slice(0, MAX_BASE_FOR_SUFFIX).replace(/-+$/, '');
  if (!base) {
    throw new InvalidHostLabelError(`Cannot derive a valid slug from name: "${name}"`);
  }

  // Treat reserved labels as unavailable alongside already-taken ones.
  const unavailable = (s: string) => RESERVED_HOST_LABELS.has(s) || isTaken(s);

  if (!unavailable(base)) return base;

  for (let n = 2; n <= 9; n++) {
    const candidate = `${base}-${n}`;
    if (!unavailable(candidate)) return candidate;
  }

  const suffix = randomSuffix();
  const candidate = `${base}-${suffix}`;
  if (!unavailable(candidate)) return candidate;

  throw new InvalidHostLabelError(
    `All slug variants for "${name}" are taken (base "${base}" through suffix "${suffix}")`,
  );
}

/**
 * Derives the Organization Host Label: slugified name truncated to MAX_ORG_NAME_SLUG_LENGTH,
 * then "-{suffix}". Unique by construction — no collision loop.
 * Trailing hyphens from truncation are stripped to prevent "--".
 */
export function deriveOrgHostLabel(orgName: string, suffix: string): string {
  const nameSlug = slugifyHostLabel(orgName).slice(0, MAX_ORG_NAME_SLUG_LENGTH).replace(/-+$/, '');
  if (!nameSlug) {
    throw new InvalidHostLabelError(`Cannot derive an org host label from name: "${orgName}"`);
  }
  return `${nameSlug}-${suffix}`;
}

/**
 * Composes the full app host: {appSlug}--{orgHostLabel}.{servingDomain} — a single DNS
 * label so the serving domain's one-level wildcard certificate covers it.
 * Parameter order matches the output order left-to-right.
 * The serving domain is always a parameter — no domain literal in this module.
 * Throws when the composed label exceeds 63 chars, which derivation prevents but a
 * hand-written or legacy org label could not.
 */
export function appHost(appSlug: string, orgHostLabel: string, servingDomain: string): string {
  const label = `${appSlug}${HOST_LABEL_SEPARATOR}${orgHostLabel}`;
  if (label.length > MAX_HOST_LABEL_LENGTH) {
    throw new InvalidHostLabelError(
      `Composed host label "${label}" is ${label.length} chars, over the ${MAX_HOST_LABEL_LENGTH}-char DNS limit`,
    );
  }
  return `${label}.${servingDomain}`;
}
