import { createHash } from 'node:crypto';
import { validateBundle, type PriorAppVersion } from './validate.js';
import { writeBundleArchive } from './archive.js';
import { appThumbnailKey, type AppObjectStore } from './object-store.port.js';
import {
  type AppVersionRecord,
  type AppVersionStore,
  type SaveAppVersionInput,
} from './app-version.js';
import { type AppEventSink, APP_VERSION_SAVE_REJECTED } from './app-events.js';

export interface SaveAppVersionDeps {
  objectStore: AppObjectStore;
  versionStore: AppVersionStore;
  events: AppEventSink;
}

/**
 * Save a validated App Version: validate → archive bytes → record provenance.
 *
 * versionId is supplied by the caller so Temporal retries reuse the same id.
 * Archive write is idempotent (skipped when key already exists).
 * insertAppVersion is idempotent on versionId.
 */
export async function saveAppVersion(
  input: SaveAppVersionInput,
  deps: SaveAppVersionDeps,
): Promise<AppVersionRecord> {
  const {
    versionId,
    appId,
    taskId,
    creatorMembershipId,
    entries,
    forbiddenLiterals,
    thumbnailBytes,
  } = input;
  const { objectStore, versionStore, events } = deps;

  // 1. Fetch prior version for schema-fingerprint / migration context.
  const prior = await versionStore.getLatestAppVersion(appId);
  const priorAppVersion: PriorAppVersion | null = prior
    ? { schemaFingerprint: prior.schemaFingerprint, migrations: prior.migrations }
    : null;

  // 2. Validate bundle — on any packaging error, emit rejection event then rethrow.
  let manifest;
  try {
    ({ manifest } = validateBundle(entries, { priorAppVersion, forbiddenLiterals }));
  } catch (err) {
    try {
      await events.emitAppEvent({
        type: APP_VERSION_SAVE_REJECTED,
        appId,
        taskId,
        data: { reason: err instanceof Error ? err.message : String(err) },
      });
    } catch {
      // best-effort: an event-sink failure must never mask the packaging-contract error
    }
    throw err;
  }

  // 3. Serialize bundle to archive bytes.
  const bytes = writeBundleArchive(entries);

  // 4. SHA-256 of the archive bytes.
  const archiveSha256 = createHash('sha256').update(bytes).digest('hex');

  // 5. Write archive under per-Version key, guarded by exists for idempotency.
  const archiveKey = `apps/${appId}/versions/${versionId}`;
  if (!(await objectStore.exists(archiveKey))) {
    await objectStore.putImmutable(archiveKey, bytes);
  }

  let thumbnailKey: string | undefined;
  if (thumbnailBytes !== undefined) {
    thumbnailKey = appThumbnailKey(appId, versionId);
    if (!(await objectStore.exists(thumbnailKey))) {
      await objectStore.putImmutable(thumbnailKey, thumbnailBytes);
    }
  }

  // 6. Build and record the AppVersion (idempotent on versionId).
  const record: AppVersionRecord = {
    versionId,
    appId,
    taskId,
    creatorMembershipId,
    archiveKey,
    archiveSha256,
    ...(thumbnailKey ? { thumbnailKey } : {}),
    schemaFingerprint: manifest.schemaFingerprint,
    migrations: manifest.migrations,
    createdAt: new Date(),
  };
  return versionStore.insertAppVersion(record);
}
